import { achievements, audiences, cameras, cases, employeePool, equipment, genres, mechanics, navItems, platforms, publishers, research, roles, scopes, settings, traits } from './data.js?v=4';
import { formatMoney } from './engine.js?v=4';

const esc = (value) => String(value ?? '').replace(/[&<>'"]/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[char]));
const pct = (value) => `${Math.round(value)}%`;
const labelFor = (list, key) => list.find((item) => item.id === key)?.label || key;
const toneClass = (tone) => tone || 'info';
const screenLabels = { dashboard: 'Главная', projects: 'Игры', team: 'Команда', office: 'Офис', research: 'Исследования', market: 'Рынок', finance: 'Финансы', luck: 'Удача', achievements: 'Достижения', history: 'История', settings: 'Настройки' };
const disciplineLabels = { programming: 'Программирование', design: 'Дизайн', art: 'Графика', audio: 'Звук', writing: 'Сценарий', qa: 'Тестирование' };
const outcomeLabels = { 'Cult Classic': 'Культовая игра', 'Commercial Hit': 'Коммерческий хит', 'Critical Hit': 'Хит у критиков', 'Long Seller': 'Долгий продавец', Failure: 'Провал', 'Solid Release': 'Крепкий релиз' };
const weightedPick = (list) => { const total = list.reduce((sum, item) => sum + item.weight, 0); let roll = Math.random() * total; for (const item of list) { roll -= item.weight; if (roll <= 0) return item; } return list[list.length - 1]; };
const randInt = (min, max) => Math.floor(min + Math.random() * (max - min + 1));
const icon = (name, size = 18) => { const ALIAS = { dashboard: 'home', history: 'doc', research: 'flask', finance: 'money', market: 'chart', luck: 'spark', achievements: 'trophy', office: 'office', team: 'users', projects: 'gamepad', settings: 'gear', programmer: 'code', designer: 'skill', artist: 'palette', audio: 'headset', writer: 'envelope', router: 'spark', server: 'code', 'audio-booth': 'headset', 'render-farm': 'palette', 'debug-kit': 'heart' }; name = ALIAS[name] || name; const p = (d) => `<path d="${d}"/>`; const c = (d) => `<circle cx="9" cy="9" r="7"/>`; const g = { stroke: 'currentColor', 'stroke-width': '1.7', fill: 'none', 'stroke-linecap': 'round', 'stroke-linejoin': 'round', width: size, height: size, viewBox: '0 0 18 18' }; const P = { home: 'M2.5 8.5 9 3l6.5 5.5M4 7.5V15h10V7.5', gamepad: 'M6 11.5v2M5 12.5h2M12.5 11.5h.01M14.5 12.5h.01M3 11.5l-.9-5.6a1 1 0 0 1 1-1.2h9.8a1 1 0 0 1 1 1.2L13 11.5', users: 'M6 8a2.2 2.2 0 1 0 0-4.4A2.2 2.2 0 0 0 6 8Zm6.2-.4a2 2 0 1 0 0-3.6M2.6 14.2a4.4 4.4 0 0 1 6.8 0M11.5 11a4 4 0 0 1 3.8.6', office: 'M2 14.5h14M3.5 6.5h-1.5V14.5M3.5 6.5H7V4h4v2.5h3.5V14.5M6 6v2m2-2v2m2-2v2m2-2v2', flask: 'M8 2.6v4.4L3.6 13a1.6 1.6 0 0 0 1.4 2.4h6a1.6 1.6 0 0 0 1.4-2.4L8 7V2.6M8 2.6h2M4 9h8', chart: 'M3 14.5V10m4 4.5V6m4 8.5V8m4 6.5V3.5', money: 'M2.5 5.5h13v7h-13zm2.8 3.5h.01m5 1.5h3.5M12.5 8h.01M4 11h.01', spark: 'M9 2.5 10 8l5.5 1-5.5 1L9 15.5 8 10 2.5 9 8 8Z', trophy: 'M5.5 3.5h7V8a3.5 3.5 0 0 1-7 0Zm-2 0h2M13.5 3.5h2M9 11.5v2m-3.5 0h7v1.5h-7Z', goal: 'M3.5 9a5.5 5.5 0 1 0 11 0 5.5 5.5 0 0 0-11 0Zm3.2 0A2.3 2.3 0 0 1 9 6.7M9 9l2-1.2', gear: 'M9 11.2a2.2 2.2 0 1 0 0-4.4 2.2 2.2 0 0 0 0 4.4Zm4.9-2.6c-.5-3.8-2-5.1-2-5.1L9 6.2 5.6 3.5s-1.4 1.3-2 5.1L1 7.3c.4 1.3 2.2 3.2 2.2 3.2S3.2 12.4 3.6 13l2.8-.6c.5 3.6 1.9 4.9 1.9 4.9s1.5-1.3 2-4.9l2.8.6c.4-.6-.8-2.4-.8-2.4s1.8-1.9 2.2-3.4Z', envelope: 'M2.5 5h13v9h-13zM2.5 5.5 9 10l6.5-4.5', ticket: 'M3 5h12v3.2a1.6 1.6 0 0 0 0 2.6V14H3V10.8a1.6 1.6 0 0 0 0-2.6Zm1.5 5.5h.01m4 0h.01m4 0h.01', star: 'M9 2.5 11 7l4.5.5-3.3 3 .9 4.5L9 13l-4.1 2 .9-4.5-3.3-3L7 7Z', doc: 'M6 2.5h6l2.5 2.5v10.5H6zm2 5h5M8 10h5M8 12.5h3', skill: 'M9 2.5v3m0 7v3M2.5 9h3m7 0h3M5 5l2 2m6 6 2 2m0-10-2 2M5 13l2-2', heart: 'M9 14 4 8.8a3 3 0 0 1 4.2-4.2L9 5.6l.8-1A3 3 0 0 1 14 8.8Z', code: 'M5.5 6 2.5 9l3 3m7-6 3 3-3 3M10 4.5l-2 9' }; const Q = { alarm: c('<circle cx="9" cy="9" r="6"/>') + '<path d="M9 5.5V9l2.2 1.6M6 2.5 3.5 5M12 2.5 14.5 5" stroke="currentColor" stroke-width="1.6" fill="none" stroke-linecap="round"/>', headset: c('<circle cx="9" cy="9" r="6"/>') + '<path d="M5 13.5V9a4 4 0 0 1 8 0v4.5" stroke="currentColor" stroke-width="1.6" fill="none" stroke-linecap="round"/>', video: '<rect x="2.5" y="5" width="10" height="8" rx="1" stroke="currentColor" stroke-width="1.6" fill="none"/><path d="m12.5 8 3-2v6l-3-2" stroke="currentColor" stroke-width="1.6" fill="none" stroke-linejoin="round"/>', palette: c('<circle cx="9" cy="9" r="6.5"/>') + '<path d="M9 5.5a3.5 3.5 0 0 0 0 7h1a1.2 1.2 0 0 1 0 2.4" stroke="currentColor" stroke-width="1.6" fill="none"/><circle cx="6.5" cy="9" r=".6" fill="currentColor" stroke="none"/><circle cx="11.5" cy="7" r=".6" fill="currentColor" stroke="none"/>' }; const B = { user: '<circle cx="9" cy="6" r="2.5" stroke="currentColor" stroke-width="1.6" fill="none"/><path d="M4 14.5a5 5 0 0 1 10 0" stroke="currentColor" stroke-width="1.6" fill="none" stroke-linecap="round"/>', bank: '<rect x="2.5" y="7" width="13" height="2" fill="currentColor" opacity=".9"/><path d="M9 2.5 2.5 5.5h13Zm0 5v7M6.5 12.5h5M6 7h6" stroke="currentColor" stroke-width="1.5" fill="none" stroke-linecap="round"/>', dice: '<rect x="3.5" y="3.5" width="11" height="11" rx="2" stroke="currentColor" stroke-width="1.6" fill="none"/><circle cx="7" cy="7" r=".8" fill="currentColor" stroke="none"/><circle cx="11" cy="11" r=".8" fill="currentColor" stroke="none"/>' }; const S = { P, Q, B }; const sel = (P[name] && 'P') || (Q[name] && 'Q') || (B[name] && 'B') || (name === 'user' ? 'B' : 'P'); let body = ''; if (sel === 'P') body = p(P[name] || P.home); else if (sel === 'Q') body = Q[name]; else body = B[name]; return `<svg class="line-icon line-icon-${name}" ${Object.entries(g).map(([k, v]) => `${k}="${v}"`).join(' ')}>${body}</svg>`; };

export class UI {
  constructor(engine, root, toastRegion, audio) { this.engine = engine; this.root = root; this.toastRegion = toastRegion; this.audio = audio; this.modal = null; this.releaseTimer = null; this.menuOpen = false; engine.subscribe(() => { this.audio?.setEnabled(engine.getState().settings.sound); this.render(); }); }
  mount() { this.render(); }

  render() {
    const state = this.engine.getState();
    if (state.bankrupt) { this.root.innerHTML = this.bankruptView(); this.bind(); return; }
    const nav = navItems.map(([id, label, glyph]) => `<button class="nav-item ${state.screen === id ? 'active' : ''}" data-action="nav" data-screen="${id}"><span class="nav-icon">${icon(id)}</span><span>${label}</span>${id === 'dashboard' && state.events.length ? '<i class="nav-dot"></i>' : ''}</button>`).join('');
    this.root.innerHTML = `<aside class="sidebar"><div class="brand"><span class="brand-mark">404</span><div><strong>STUDIO</strong><small>СОЗДАВАЙ ИГРЫ</small></div></div><nav>${nav}</nav><div class="sidebar-foot"><div class="save-state"><span class="live-dot"></span> Локальное сохранение</div><button class="text-button" data-action="save">Сохранить прогресс <span>Ctrl S</span></button><div class="version">v0.1 / ранняя версия</div></div></aside><main class="main"><header class="topbar"><div class="crumb"><span class="mobile-brand">404</span><span class="eyebrow">${state.screen === 'dashboard' ? 'Рабочий день' : screenLabels[state.screen]}</span><span class="slash">/</span><strong>${screenLabels[state.screen] || 'Главная'}</strong></div><div class="top-actions"><span class="date">${state.month.toString().padStart(2, '0')} / ${state.year}</span><button class="icon-button ${state.paused ? 'is-paused' : ''}" data-action="pause" title="Пауза">${state.paused ? '▶' : 'Ⅱ'}</button><button class="avatar" data-action="nav" data-screen="team"><span class="avatar-icon">${icon('user', 20)}</span></button></div></header><section class="page-content">${this.page(state)}</section></main>${state.pendingCredit ? this.creditModal(state) : this.modal ? this.modalView(state) : ''}`;
    this.bind();
    if (this.root.insertAdjacentHTML && state.saveNotice && Date.now() - state.saveNotice < 1800) this.root.insertAdjacentHTML('beforeend', '<div class="save-indicator"><span></span>Игра сохраняется</div>');
    this.root.querySelectorAll('button').forEach((button) => { if (!button.dataset.soundBound) { button.dataset.soundBound = '1'; button.addEventListener('click', () => this.audio?.play('click'), true); } });
    this.root.querySelectorAll('[data-action="work-mode"]').forEach((button) => button.addEventListener('click', () => { this.engine.setWorkMode(button.dataset.mode); }));
    this.root.querySelectorAll('input[type="range"]').forEach((input) => input.addEventListener('input', () => { const output = input.closest('label')?.querySelector('output'); if (output) output.textContent = input.name === 'price' ? `$${Number(input.value).toFixed(2)}` : Number(input.value).toLocaleString('ru-RU'); }));
    this.root.querySelectorAll('[data-action="marketing"]').forEach((button) => { if (state.currentProject?.marketingUsed?.includes(button.dataset.marketing) || state.currentProject?.marketing >= 100) button.disabled = true; });
    if (state.currentProject?.phase === 'release-ready') this.root.querySelectorAll('[data-action="advance"]').forEach((button) => { button.disabled = true; });
    const equipmentHost = this.root.querySelector('.office-info'); if (equipmentHost) { equipmentHost.insertAdjacentHTML('beforeend', `<div class="equipment-shop"><div class="equipment-heading"><span class="kicker">Мастерская</span><strong>Оборудование для офиса</strong></div>${equipment.map((item) => { const owned = state.equipment.includes(item.id); return `<div class="equipment-item ${owned ? 'owned' : ''}"><span class="equipment-icon">${icon(item.id, 18)}</span><div><strong>${item.label}</strong><small>${item.description}</small><em>${item.effect}</em></div><button class="small-button" data-action="buy-equipment" data-equipment="${item.id}" ${owned || state.money < item.cost ? 'disabled' : ''}>${owned ? 'Куплено' : formatMoney(item.cost)}</button></div>`; }).join('')}</div>`); equipmentHost.querySelectorAll('[data-action="buy-equipment"]').forEach((button) => button.addEventListener('click', () => { this.audio?.play('click'); this.engine.buyEquipment(button.dataset.equipment); this.toast('Оборудование установлено.', 'success'); })); }
  }

  page(state) { const pages = { dashboard: this.dashboard, projects: this.projects, team: this.team, office: this.office, research: this.researchPage, market: this.market, finance: this.finance, luck: this.luck, achievements: this.achievementsPage, history: this.history, settings: this.settingsPage }; return (pages[state.screen] || this.dashboard).call(this, state); }

  dashboard(state) {
    const p = state.currentProject; const totalProgress = p ? Object.values(p.progress).reduce((sum, value) => sum + value, 0) / 6 : 0;
    return `<div class="page-heading"><div><span class="kicker">${state.studioName} / ${state.officeStage === 1 ? 'Первая комната' : `Офис, стадия ${state.officeStage}`}</span><h1>Сделай следующую <em>хорошую</em> игру.</h1><p class="lede">Маленькая студия с собственным голосом. Делай работу честно.</p></div><button class="button primary" data-action="open-create" ${p ? 'disabled' : ''}>${p ? 'Проект в работе' : '+ Новая игра'}</button></div><div class="stat-grid"><div class="stat-card money"><span>Запас денег</span><strong>${formatMoney(state.money)}</strong><small>${state.team.length} ${state.team.length === 1 ? 'человек' : 'человека'} / репутация ${state.reputation}</small></div><div class="stat-card"><span>Текущий проект</span><strong>${p ? pct(totalProgress) : '—'}</strong><small>${p ? esc(p.name) : 'На доске пусто'}</small></div><div class="stat-card"><span>Пульс рынка</span><strong>${this.marketPulse(state)}<i>/100</i></strong><small>${this.marketTrend(state)}</small></div><div class="stat-card"><span>Решения</span><strong>${p ? p.issues.filter((issue) => issue.status === 'open').length : 0}</strong><small>Ждут твоего внимания</small></div></div>${this.tutorial(state)}${p ? this.projectBoard(state, p) : state.lastRelease ? this.postRelease(state) : this.emptyBoard(state)}<div class="dashboard-lower"><section class="panel events-panel"><div class="panel-head"><div><span class="kicker">Сигналы / ${state.events.length}</span><h2>Последние события</h2></div><button class="link-button" data-action="nav" data-screen="history">Вся история ↗</button></div>${this.events(state.events.slice(0, 4))}</section><section class="panel studio-panel"><div class="panel-head"><div><span class="kicker">Состояние студии</span><h2>Как чувствует себя команда</h2></div></div>${this.health(state)}</section></div>`;
  }

  tutorial(state) {
    if (!state.settings.tutorial || state.tutorialCompleted) return '';
    const steps = [
      ['Шаг 1 / идея', 'Создай первую игру', 'Выбери жанр, механику и масштаб. Прогноз покажет риск, но не даст гарантии.', 'Открыть создание игры'],
      ['Шаг 2 / разработка', 'Проведи первый месяц', 'Каждый месяц меняет проект. Быстрый путь экономит срок, но оставляет технический долг.', 'Перейти к проекту'],
      ['Шаг 3 / решения', 'Смотри на последствия', 'Проблемы появляются из состояния проекта. Исправлять их дороже, чем не допускать.', 'Понятно'],
      ['Шаг 4 / релиз', 'Выпусти игру', 'Когда прогресс достигнет срока, реши: выпустить сейчас или купить ещё один месяц.', 'Продолжить'],
      ['Шаг 5 / студия', 'Найми первого сотрудника', 'После релиза открой команду. Новые навыки меняют то, какие игры ты можешь делать.', 'Открыть команду']
    ];
    const step = Math.min(state.tutorialStep || 0, steps.length - 1); const item = steps[step];
    return `<section class="tutorial-card"><div class="tutorial-mark">${String(step + 1).padStart(2, '0')}</div><div><span class="kicker">${item[0]}</span><h2>${item[1]}</h2><p>${item[2]}</p></div><button class="button secondary" data-action="tutorial-next">${item[3]} <span>→</span></button></section>`;
  }

  emptyBoard(state) { return `<section class="empty-board"><div class="empty-copy"><span class="number-mark">01</span><div><span class="kicker">Твоё первое решение</span><h2>Положи идею на доску.</h2><p>У тебя одна комната, один компьютер и ${formatMoney(state.money)}. Выбери направление и позволь последствиям тебя учить.</p><button class="button primary" data-action="open-create">Создать первую игру <span>→</span></button></div></div><div class="empty-sketch">${this.coverArt('exploration', true)}</div></section>`; }

  postRelease(state) { const game = state.lastRelease; return `<section class="release-result panel"><div class="release-result-head"><div><span class="kicker">Последний релиз / ${game.year}</span><h2>${esc(game.name)}</h2><p>${outcomeLabels[game.outcome] || game.outcome}${game.publisher ? ` · издатель ${game.publisher.name}` : ' · самостоятельный выпуск'}</p></div><strong>${game.rating.toFixed(1)}<small>/10</small></strong></div><div class="review-list">${game.reviews.map((review) => `<div class="review-line"><span>“</span><p>${esc(review)}</p></div>`).join('')}</div><div class="release-result-foot"><span>${game.sales.toLocaleString('ru-RU')} продаж</span><span>${formatMoney(game.revenue)} выручки</span><button class="button secondary" data-action="nav" data-screen="projects">Открыть библиотеку →</button></div></section>`; }

  projectBoard(state, p) {
    const total = Object.values(p.progress).reduce((sum, value) => sum + value, 0) / 6; const disciplines = Object.entries(p.progress).map(([key, value]) => `<div class="progress-line"><div><span>${disciplineLabels[key] || key}</span><b>${pct(value)}</b></div><div class="progress-track"><i style="width:${value}%"></i></div></div>`).join(''); const issues = p.issues.filter((issue) => issue.status === 'open');
    return `<section class="project-board panel"><div class="project-summary"><div><span class="kicker">Текущий проект / ${p.phase === 'release-ready' ? 'Готов к релизу' : `Месяц ${p.monthsSpent} из ${p.forecast.months}`}</span><h2>${esc(p.name)}</h2><div class="tag-row"><span class="tag accent">${labelFor(genres, p.genre)}</span><span class="tag">${labelFor(settings, p.setting)}</span><span class="tag">${labelFor(scopes, p.scope)} масштаб</span></div><p class="hook">«${esc(p.hook)}»</p></div><div class="project-percent"><strong>${pct(total)}</strong><span>общая готовность</span></div></div><div class="board-body"><div class="discipline-list">${disciplines}</div><div class="board-side"><div class="mini-metric"><span>Давление бюджета</span><b>${formatMoney(Math.max(0, p.forecast.cost - p.monthsSpent * 1300))}</b></div><div class="mini-metric"><span>Технический долг</span><b class="${p.debt > 45 ? 'danger-text' : ''}">${p.debt}/100</b></div><div class="mini-metric"><span>Открытые проблемы</span><b>${issues.length}</b></div></div></div>${issues.length ? `<div class="issues"><div class="issues-title"><span>Проблемы в сборке</span><b>${issues.length}</b></div>${issues.map((issue) => `<div class="issue"><div><strong>${esc(issue.title)}</strong><p>${esc(issue.detail)}</p></div><button class="small-button" data-action="issue" data-issue="${issue.id}">Решить</button></div>`).join('')}</div>` : '<div class="quiet-note">Критических проблем нет. Это не значит, что риска нет.</div>'}<div class="work-controls"><div><span class="kicker">Выбери неделю</span><p>Быстро — бережёт срок. Правильно — бережёт будущее.</p></div><div class="button-row"><button class="button ghost" data-action="advance" data-mode="proper">Правильно <small>−скорость / −долг</small></button><button class="button secondary" data-action="advance" data-mode="normal">Рабочая неделя <small>стабильно</small></button><button class="button warning" data-action="advance" data-mode="fast">Быстро <small>+скорость / +долг</small></button><button class="button danger" data-action="advance" data-mode="crunch">Рывок <small>+скорость / выгорание</small></button></div></div><div class="marketing-strip"><div><span class="kicker">Собери аудиторию</span><p>Маркетинг — это обещание. Дай такое, которое сможешь выполнить.</p></div><div class="marketing-actions"><button class="small-button" data-action="marketing" data-marketing="trailer">Трейлер · $1 800</button><button class="small-button" data-action="marketing" data-marketing="demo">Демо · $3 200</button><button class="small-button" data-action="marketing" data-marketing="press">Пресса · $4 500</button><button class="small-button" data-action="marketing" data-marketing="influencer">Блогер · $6 500</button></div></div>${p.phase === 'release-ready' ? `<div class="ready-banner"><div><span class="kicker">Сборка готова</span><strong>Посмотри на результат и выбери момент.</strong></div><button class="button primary" data-action="open-release">Подготовить релиз →</button></div>` : ''}</section>`;
  }

  health(state) { const average = Math.round(state.team.reduce((sum, member) => sum + member.morale, 0) / state.team.length); const burnout = Math.round(state.team.reduce((sum, member) => sum + member.burnout, 0) / state.team.length); return `<div class="health-row"><span>Мораль</span><div class="health-track"><i class="success-fill" style="width:${average}%"></i></div><b>${average}</b></div><div class="health-row"><span>Выгорание</span><div class="health-track"><i class="${burnout > 45 ? 'danger-fill' : 'warning-fill'}" style="width:${burnout}%"></i></div><b>${burnout}</b></div><div class="health-note"><span class="signal-icon">${burnout > 45 ? '!' : '✓'}</span><p>${burnout > 45 ? 'Команде нужен спокойный месяц.' : 'У команды есть пространство для хорошей работы.'}</p></div><button class="link-button" data-action="nav" data-screen="team">Проверить команду →</button>`; }
  events(list) { return list.length ? `<div class="event-list">${list.map((event) => `<article class="event-item"><span class="event-marker ${toneClass(event.tone)}"></span><div><div class="event-meta">${event.month ? `${event.month.toString().padStart(2, '0')} / ` : ''}${event.year} <span>${({ info: 'сигнал', warning: 'внимание', danger: 'опасность', success: 'успех' })[event.tone] || event.tone}</span></div><h3>${esc(event.title)}</h3><p>${esc(event.text)}</p></div></article>`).join('')}</div>` : '<p class="muted">Событий пока нет.</p>'; }

  projects(state) { const current = state.currentProject ? `<section class="panel active-project"><div class="panel-head"><div><span class="kicker">Сейчас на доске</span><h2>${esc(state.currentProject.name)}</h2></div><span class="status-pill">В разработке</span></div><p class="hook">«${esc(state.currentProject.hook)}»</p><button class="button secondary" data-action="nav" data-screen="dashboard">Открыть доску проекта →</button></section>` : ''; const cards = state.projects.length ? state.projects.map((game) => `<article class="game-card"><div class="cover ${game.genre}">${this.coverArt(game.genre)}<span>404</span><b>${esc(game.name)}</b><small>${labelFor(genres, game.genre)} / ${game.year}</small></div><div class="game-details"><div class="game-top"><div><span class="kicker">${outcomeLabels[game.outcome] || game.outcome}</span><h3>${esc(game.name)}</h3></div><div class="card-rating">${this.stars(Math.round(game.rating / 2))}<strong class="rating">${game.rating.toFixed(1)}<small>/10</small></strong></div></div><div class="tag-row"><span class="tag">${labelFor(settings, game.setting)}</span><span class="tag">${game.sales.toLocaleString('ru-RU')} продаж</span></div><div class="game-stats"><span>Выручка <b>${formatMoney(game.revenue)}</b></span><span>Техника <b>${game.scores.technical}</b></span><span>Инновации <b>${game.scores.innovation}</b></span></div><div class="sales-chart"><span>Продажи за первые четыре месяца</span><div>${game.salesTrend.map((value) => `<i style="height:${Math.max(8, Math.round(value / Math.max(...game.salesTrend) * 100))}%"><b>${Math.round(value / 1000)} тыс.</b></i>`).join('')}</div></div><div class="review-quote">«${esc(this.reviewText(game.reviews[0]))}»</div><button class="small-button" data-action="dlc" data-project="${game.id}" ${game.dlcMade ? 'disabled' : ''}>${game.dlcMade ? 'Дополнение уже вышло' : 'Сделать небольшое дополнение · $7 000'}</button></div></article>`).join('') : '<div class="blank-state"><span class="number-mark">02</span><h2>Полка пока пуста.</h2><p>Каждая выпущенная игра станет частью истории студии.</p></div>'; return `<div class="page-heading"><div><span class="kicker">Архив / ${state.projects.length}</span><h1>Твои игры.</h1><p class="lede">Решения уже внутри сборки. Можно посмотреть назад, но нельзя их переписать.</p></div><button class="button primary" data-action="open-create" ${state.currentProject ? 'disabled' : ''}>+ Новая игра</button></div>${current}<section class="game-shelf">${cards}</section>`; }

  team(state) { const cards = state.team.map((member) => { const role = roles.find((entry) => entry.id === member.role); const trait = traits.find((entry) => entry.id === member.trait); return `<article class="person-card"><div class="person-avatar ${member.role}">${icon(member.role, 22)}</div><div class="person-intro"><span class="kicker">${role?.label || member.role} / уровень ${member.level}</span><h3>${esc(member.name)}</h3><span class="trait">${trait?.label || member.trait} <small>${trait?.effect || ''}</small></span></div><div class="person-bars"><div class="person-bar"><span>Мораль</span><i><b class="success-fill" style="width:${member.morale}%"></b></i><strong>${member.morale}</strong></div><div class="person-bar"><span>Выгорание</span><i><b class="${member.burnout > 45 ? 'danger-fill' : 'warning-fill'}" style="width:${member.burnout}%"></b></i><strong>${member.burnout}</strong></div></div>${member.isFounder ? '<span class="founder-mark">ОСНОВАТЕЛЬ</span>' : `<button class="icon-link" data-action="fire" data-member="${member.id}">Уволить</button>`}</article>`; }).join(''); const candidates = employeePool.map((candidate, index) => { const role = roles.find((entry) => entry.id === candidate.role); const hired = state.team.some((member) => member.name === candidate.name); return `<div class="candidate"><div class="candidate-avatar">${icon(candidate.role, 20)}</div><div><strong>${candidate.name}</strong><span>${role.label} · ${traits.find((trait) => trait.id === candidate.trait)?.label}</span></div><button class="small-button" data-action="hire" data-candidate="${index}" ${hired ? 'disabled' : ''}>${hired ? 'В команде' : `Нанять · ${formatMoney(role.salary * 2)}`}</button></div>`; }).join(''); return `<div class="page-heading"><div><span class="kicker">Люди / ${state.team.length}</span><h1>Люди делают студию.</h1><p class="lede">Навыки видны. Доверие, усталость и отношения — нет.</p></div></div><section class="team-grid">${cards}</section><section class="panel hiring-panel"><div class="panel-head"><div><span class="kicker">Открытые роли</span><h2>С кем можно работать</h2></div><span class="muted">Два оклада вперёд</span></div><div class="candidate-list">${candidates}</div></section>`; }

  office(state) { const desks = Math.min(8, state.team.length + state.officeStage - 1); const deskMarkup = Array.from({ length: desks }, (_, index) => `<div class="desk desk-${index + 1}"><span class="monitor"></span><i class="person-dot ${state.team[index % state.team.length].burnout > 45 ? 'tired' : ''}"></i></div>`).join(''); const roomNames = ['Второй стол', 'Место для мыслей', 'Настоящая студия', 'Большая компания']; return `<div class="page-heading"><div><span class="kicker">Пространство / стадия ${state.officeStage} из 5</span><h1>Комната, которая помнит.</h1><p class="lede">Офис не просто награда. Это ограничение, которое ощущается в работе.</p></div></div><section class="office-layout"><div class="office-scene stage-${state.officeStage}"><div class="scene-label">${esc(state.studioName || 'STUDIO')} / ${state.year}</div><div class="window-light"></div><div class="plant"></div>${deskMarkup}<div class="whiteboard"><span>ДЕЛАЙ<br />ХОРОШУЮ<br />РАБОТУ</span></div><div class="server-stack"><i></i><i></i><i></i></div></div><div class="office-info panel"><span class="kicker">Следующая комната</span><h2>${state.officeStage >= 5 ? 'Здесь достаточно места.' : roomNames[state.officeStage - 1]}</h2><p>${state.officeStage >= 5 ? 'Студия достигла последней запланированной площади. Теперь важнее то, что ты с ней делаешь.' : 'Больше пространства упрощает найм и даёт команде немного воздуха.'}</p><div class="office-cost"><span>Цена расширения</span><strong>${state.officeStage >= 5 ? 'МАКСИМУМ' : formatMoney(state.officeUpgradeCost)}</strong></div><button class="button primary" data-action="upgrade-office" ${state.officeStage >= 5 || state.money < state.officeUpgradeCost ? 'disabled' : ''}>${state.officeStage >= 5 ? 'Офис завершён' : 'Расширить офис'}</button><small class="muted">${state.officeStage < 5 && state.money < state.officeUpgradeCost ? `Нужно ещё ${formatMoney(state.officeUpgradeCost - state.money)}.` : 'Долгосрочная инвестиция в людей.'}</small></div></section>`; }

  researchPage(state) { const cards = research.map((tech) => { const unlocked = state.research.includes(tech.id); const available = tech.requires.every((item) => state.research.includes(item)); return `<article class="research-card ${unlocked ? 'unlocked' : !available ? 'locked' : ''}"><div class="research-symbol">${unlocked ? '✓' : '◈'}</div><div><span class="kicker">${unlocked ? 'Исследовано' : tech.requires.length ? `Нужно: ${tech.requires.map((req) => labelFor(research, req)).join(', ')}` : 'Доступно сейчас'}</span><h3>${tech.label}</h3><p>${tech.description}</p></div><button class="small-button" data-action="research" data-tech="${tech.id}" ${unlocked || !available || state.money < tech.cost ? 'disabled' : ''}>${unlocked ? 'Готово' : formatMoney(tech.cost)}</button></article>`; }).join(''); return `<div class="page-heading"><div><span class="kicker">Исследования / открыто ${state.research.length}</span><h1>Инвестируй в хорошие вопросы.</h1><p class="lede">Исследования меняют работу, а не только цифру на карточке.</p></div></div><section class="research-grid">${cards}</section>`; }

  market(state) { const rows = genres.map((genre) => { const value = state.market[genre.id]; const competitor = state.competitors.find((entry) => entry.genre === genre.id); return `<div class="market-row"><div class="market-name"><strong>${genre.label}</strong><span>${competitor ? `${competitor.name} активна здесь` : 'Место для нового голоса'}</span></div><div class="market-bar"><i style="width:${value}%"></i></div><b>${value}</b></div>`; }).join(''); const news = (state.news || []).slice(0, 6).map((item) => `<article class="news-item"><span>${String(item.month).padStart(2, '0')} / ${item.year}</span><div><strong>${item.title}</strong><p>${item.text}</p></div></article>`).join(''); return `<div class="page-heading"><div><span class="kicker">Сигнал квартала / Q${Math.ceil(state.month / 3)}</span><h1>Читай комнату.</h1><p class="lede">Следовать тренду безопаснее. Инновации помогают маленькой студии остаться в памяти.</p></div></div><section class="market-layout"><div class="panel market-panel"><div class="panel-head"><div><span class="kicker">Интерес аудитории</span><h2>Температура жанров</h2></div><span class="muted">Меняется каждый месяц</span></div>${rows}</div><div class="panel competitors-panel"><div class="panel-head"><div><span class="kicker">Ежемесячный рейтинг</span><h2>Капитал студий</h2></div><span class="muted">Обновляется каждый месяц</span></div><div class="rating-list">${(state.rating || []).map((entry) => `<div class="rating-row ${entry.isUs ? 'is-us' : ''}"><span class="rating-rank">#${entry.rank}</span><span class="rating-icon" style="--ic:${entry.color}">${esc(entry.icon)}</span><div class="rating-name"><strong>${esc(entry.name)}</strong><span>${esc(entry.note || '')}</span></div><span class="rating-cap">${formatMoney(entry.cap)}</span><span class="rating-move ${entry.move > 0 ? 'up' : entry.move < 0 ? 'down' : 'flat'}">${entry.move > 0 ? '▲' : entry.move < 0 ? '▼' : '—'}</span></div>`).join('')}</div></div></section><section class="panel news-panel"><div class="panel-head"><div><span class="kicker">Ежемесячная лента</span><h2>Новости рынка</h2></div><span class="muted">Следи за тем, что меняется вокруг</span></div>${news || '<p class="muted">Новости появятся после первого рабочего месяца.</p>'}</section>`; }

  achievementsPage(state) { const earned = new Set((state.earnedAchievements || []).map((entry) => entry.id)); const earnedMap = {}; (state.earnedAchievements || []).forEach((entry) => { earnedMap[entry.id] = entry; }); const total = achievements.reduce((sum, a) => sum + a.reward, 0); const got = achievements.reduce((sum, a) => sum + (earned.has(a.id) ? a.reward : 0), 0); const cards = achievements.map((a) => { const isEarned = earned.has(a.id); const meta = earnedMap[a.id]; return `<article class="ach-card ${isEarned ? 'earned' : ''}" style="--ac:${a.color}"><div class="ach-art"><span class="ach-icon">${a.icon}</span>${isEarned ? '<span class="ach-seal">✓</span>' : '<span class="ach-lock">🔒</span>'}</div><div class="ach-body"><span class="kicker">${a.desc}</span><h3>${esc(a.name)}</h3><p>${isEarned ? (meta ? `Получено в ${meta.month}/${meta.year}` : 'Получено') : 'Ещё не раскрыто'}</p></div><div class="ach-reward ${isEarned ? 'earned' : ''}"><span>Награда</span><b>${formatMoney(a.reward)}</b></div></article>`; }).join(''); return `<div class="page-heading"><div><span class="kicker">Достижения / ${earned.size} из ${achievements.length}</span><h1>Вехи, которые стоят денег.</h1><p class="lede">Премии приходят с выполнением условия — деньги попадают на счёт сразу. Каждое достижение срабатывает один раз.</p></div></div><div class="ach-summary"><div class="ach-sum-item"><span>Показано премией</span><b>${formatMoney(got)}</b></div><div class="ach-sum-item"><span>Доступно всего</span><b>${formatMoney(total)}</b></div><div class="ach-progress"><span>Открыто</span><div class="progress-track"><i style="width:${achievements.length ? Math.round((earned.size / achievements.length) * 100) : 0}%"></i></div></div></div><section class="ach-grid">${cards}</section>`; }

  finance(state) { const totalRevenue = state.stats.revenue; const monthlyBurn = 800 + state.team.reduce((sum, member) => sum + (roles.find((role) => role.id === member.role)?.salary || 1000), 0) * 0.24; return `<div class="page-heading"><div><span class="kicker">Финансы / ${state.year}</span><h1>Деньги — ограничение дизайна.</h1><p class="lede">Здоровый запас покупает лучшие решения. Но не принимает их за тебя.</p></div></div><div class="finance-stats"><div class="stat-card money"><span>Деньги на руках</span><strong>${formatMoney(state.money)}</strong><small>Доступно сейчас</small></div><div class="stat-card"><span>Выручка за всё время</span><strong>${formatMoney(totalRevenue)}</strong><small>После ${state.stats.released} релизов</small></div><div class="stat-card"><span>Расход в месяц</span><strong>${formatMoney(monthlyBurn)}</strong><small>Команда и помещение</small></div></div><section class="panel finance-panel"><div class="panel-head"><div><span class="kicker">Движение денег</span><h2>Что студия уже сделала</h2></div></div><div class="ledger-list"><div><span>Стартовый запас</span><b>${formatMoney(18000)}</b></div><div><span>Выручка с релизов</span><b class="success-text">+${formatMoney(totalRevenue)}</b></div><div><span>Исследования и офис</span><b class="danger-text">Учтены в решениях</b></div><div><span>Текущий баланс</span><b>${formatMoney(state.money)}</b></div></div><div class="finance-note"><span>!</span><p>Каждый месяц стоит денег, даже если проект почти не движется. Оставляй место для одного хорошего решения.</p></div></section>`; }

  luck(state) { const cards = cases.map((c) => { const loot = c.loot.map((item) => `<li style="--c:${item.color}"><span>${esc(item.label)}</span><b>${formatMoney(item.min)}–${formatMoney(item.max)}</b></li>`).join(''); const canAfford = state.money >= c.price; return `<article class="case-card" style="--accent:${c.accent}"><div class="case-top"><div class="case-icon">${c.icon}</div><div><span class="kicker">Кейс</span><h3>${esc(c.name)}</h3><p>${c.odds}</p></div><strong class="case-price">${formatMoney(c.price)}</strong></div><div class="case-art"><span class="case-logo">${c.icon}</span><em>СЛУЧАЙ</em></div><ul class="case-loot-list">${loot}</ul><button class="button primary" data-action="open-luck" data-case="${c.id}" ${canAfford ? '' : 'disabled'}>${canAfford ? `Открыть за ${formatMoney(c.price)}` : 'Не хватает денег'}</button></div></article>`; }).join(''); return `<div class="page-heading"><div><span class="kicker">Удача / ${cases.length} кейса</span><h1>Студия любит риск.</h1><p class="lede">Каждый кейс стоит денег. Призы бывают и меньше, и заметно больше цены. Крупный лут — редкий.</p></div></div><section class="luck-grid">${cards}</section>`; }
  luckModal(result) { const c = cases.find((item) => item.id === result.caseId); const LEN = 32; const WIN = 20; const reel = []; for (let i = 0; i < LEN; i += 1) reel.push(weightedPick(c.loot)); reel[WIN] = result.item; const cells = reel.map((item, index) => `<div class="luck-cell ${index === WIN ? 'is-winner' : ''}" style="--c:${item.color}"><em></em><span>${esc(item.label)}</span></div>`).join(''); const ordered = (c.loot || []); const winPos = ordered.length ? (Math.max(0, ordered.indexOf(result.item)) / ordered.length) * 100 : 50; return `<div class="modal-backdrop"><div class="luck-modal"><div class="modal-head"><div><span class="kicker">Кейс / ${esc(c.name)} · ${formatMoney(c.price)}</span><h2>Вращай барабан.</h2><p>${esc(c.odds)}</p></div><button class="close-button" data-action="close-modal">×</button></div><div class="luck-window"><div class="luck-marker"></div><div class="luck-reel" data-reel="luck">${cells}</div></div><div class="prize-tape"><span class="prize-tape-label">Полоса выигрыша</span><div class="prize-tape-track"><div class="prize-tape-fill" data-fill="${winPos}"></div></div><strong data-tape="luck">${esc(result.item.label)}</strong></div><div class="luck-result" data-result="luck"><span class="luck-result-label">Твой приз</span><strong style="color:${result.item.color}">${formatMoney(result.amount)}</strong><p>${esc(result.item.label)} <small>${result.net >= 0 ? '+' : ''}${formatMoney(result.net)} к балансу</small></p><button class="button primary" data-action="close-modal">Забрать →</button></div></div></div>`; }
  spinLuck() { this.audio?.play('spin'); const reel = this.root.querySelector('[data-reel="luck"]'); if (!reel) return; const winner = reel.querySelector('.luck-cell.is-winner'); if (!winner) return; const marker = reel.closest('.luck-window')?.querySelector('.luck-marker'); const cellW = winner.offsetWidth || 72; const markerLeft = marker ? marker.offsetLeft : 216; const winIdx = Array.from(reel.children).indexOf(winner); void reel.offsetWidth; reel.style.transition = 'transform 2.8s cubic-bezier(0.12,0.75,0.15,1)'; reel.style.transform = `translateX(${markerLeft - winIdx * cellW}px)`; setTimeout(() => { reel.classList.add('struck'); const fill = this.root.querySelector('.prize-tape-fill'); if (fill) { fill.style.transition = 'width 1.6s cubic-bezier(0.16,0.85,0.3,1)'; fill.style.width = `${fill.dataset.fill}%`; } winner.classList.add('won'); const out = this.root.querySelector('[data-result="luck"]'); if (out) out.classList.add('show'); this.audio?.play('win'); }, 2900); }
  history(state) { const achievements = ['Первый релиз', 'Первый сотрудник', 'Идеальная оценка', 'Культовая игра', 'Без переработок'].map((achievement) => `<div class="achievement ${state.achievements.includes(achievement) ? 'earned' : ''}"><span>${state.achievements.includes(achievement) ? '✓' : '—'}</span><strong>${achievement}</strong></div>`).join(''); return `<div class="page-heading"><div><span class="kicker">Хронология / записей ${state.history.length}</span><h1>След, который ты оставил.</h1><p class="lede">Студия — это сумма решений, принятых под давлением.</p></div></div><div class="history-layout"><section class="panel timeline-panel">${state.history.map((entry) => `<article class="timeline-entry"><span>${entry.year}</span><div><h3>${esc(entry.title)}</h3><p>${esc(entry.text)}</p></div></article>`).join('')}</section><section class="panel achievements-panel"><div class="panel-head"><div><span class="kicker">Вехи</span><h2>Заслужено честно</h2></div></div>${achievements}<div class="reputation-card"><span class="kicker">Репутация студии</span><strong>${state.reputation}</strong><p>${this.reputationLabel(state.reputation)}</p><div class="progress-track"><i style="width:${state.reputation}%"></i></div></div></section></div>`; }

  settingsPage(state) { return `<div class="page-heading"><div><span class="kicker">Управление / локальный профиль</span><h1>Держи сигнал чистым.</h1><p class="lede">Несколько практичных настроек для спокойной сессии. Сохранение остаётся на этом устройстве.</p></div></div><section class="panel settings-panel"><div class="setting-row"><div><strong>Звуковые сигналы</strong><p>Оставить небольшие звуки обратной связи включёнными, когда аудио появится в сборке.</p></div><button class="toggle ${state.settings.sound ? 'on' : ''}" data-action="toggle-setting" data-setting="sound"><i></i><span>${state.settings.sound ? 'Вкл.' : 'Выкл.'}</span></button></div><div class="setting-row"><div><strong>Обучение первой сессии</strong><p>Показывать подсказки во время решений первого проекта.</p></div><button class="toggle ${state.settings.tutorial ? 'on' : ''}" data-action="toggle-setting" data-setting="tutorial"><i></i><span>${state.settings.tutorial ? 'Вкл.' : 'Выкл.'}</span></button></div><div class="settings-divider"></div><div class="setting-row"><div><strong>Состояние сохранения</strong><p>Автосохранение работает после каждого решения. Ручное сохранение доступно в боковой панели.</p></div><span class="save-badge">ЛОКАЛЬНО / АКТИВНО</span></div><div class="settings-danger"><div><strong>Начать сначала</strong><p>Стереть эту студию и начать новую историю с первой комнаты.</p></div><button class="button ghost" data-action="reset">Сбросить сохранение</button></div></section>`; }

  marketPulse(state) { return Math.round(Object.values(state.market).reduce((sum, value) => sum + value, 0) / Object.values(state.market).length); }
  marketTrend(state) { const pulse = this.marketPulse(state); return pulse > 65 ? 'Аудитория смотрит сюда' : pulse > 45 ? 'Есть место для идеи' : 'Осторожный квартал'; }
  reputationLabel(value) { return value < 20 ? 'Пока никто' : value < 40 ? 'Маленькая студия' : value < 60 ? 'Узнаваемые' : value < 80 ? 'Крупная студия' : value < 95 ? 'Лидер индустрии' : 'Легенда'; }

  coverArt(genre, compact = false) { const cls = compact ? 'cover-art compact' : 'cover-art'; const C = { rpg: '#b5d269', horror: '#e48a9c', puzzle: '#e5ba72', shooter: '#8db6dc', strategy: '#9cbea7', simulator: '#9bc3bc', platformer: '#d59b67', racing: '#d9a6d4', exploration: '#94b8d9' }; const c = C[genre] || C.exploration; const dark = '#111318';
    switch (genre) {
      case 'rpg': return `<svg class="${cls}" viewBox="0 0 160 145" aria-hidden="true"><circle cx="118" cy="30" r="26" fill="${c}" opacity=".18"/><path d="M80 120 42 86 52 56l28 28 28-28 10 30Z" fill="${c}" opacity=".8"/><path d="m80 120 16-40" stroke="${dark}" stroke-width="3"/><circle cx="80" cy="34" r="7" fill="${c}"/><path d="M70 42 62 60h36l-8-18" fill="${c}" opacity=".7"/><circle cx="80" cy="72" r="9" fill="${c}" opacity=".45"/><path d="M24 128h112" stroke="${c}" stroke-width="2" opacity=".8"/></svg>`;
      case 'horror': return `<svg class="${cls}" viewBox="0 0 160 145" aria-hidden="true"><circle cx="120" cy="26" r="22" fill="${c}" opacity=".14"/><path d="M80 118 42 64h22l16-26 16 26h22Z" fill="${c}" opacity=".85"/><circle cx="70" cy="70" r="4" fill="${dark}"/><circle cx="90" cy="70" r="4" fill="${dark}"/><path d="M73 82h14" stroke="${dark}" stroke-width="3"/><path d="m42 38 9 12 7-14 8 15 7-13" fill="${c}" opacity=".6"/><path d="M24 130h112" stroke="${c}" stroke-width="2" opacity=".8"/></svg>`;
      case 'puzzle': return `<svg class="${cls}" viewBox="0 0 160 145" aria-hidden="true"><circle cx="122" cy="24" r="20" fill="${c}" opacity=".14"/><path d="M54 96h28v-17a8 8 0 0 1 16 0v17h28v-15a8 8 0 0 0-8-8H98V48a8 8 0 0 0-16 0v25H54v-17a8 8 0 0 0-16 0v17h-6v26h6a8 8 0 0 0 16 0Z" fill="${c}" opacity=".85"/><path d="M24 128h112" stroke="${c}" stroke-width="2" opacity=".8"/></svg>`;
      case 'shooter': return `<svg class="${cls}" viewBox="0 0 160 145" aria-hidden="true"><circle cx="118" cy="26" r="22" fill="${c}" opacity=".14"/><circle cx="80" cy="76" r="26" fill="none" stroke="${c}" stroke-width="3"/><circle cx="80" cy="76" r="7" fill="${c}"/><path d="M80 34v18M80 100v12M44 76h20M96 76h20" stroke="${c}" stroke-width="4" stroke-linecap="round"/><path d="M24 128h112" stroke="${c}" stroke-width="2" opacity=".8"/></svg>`;
      case 'strategy': return `<svg class="${cls}" viewBox="0 0 160 145" aria-hidden="true"><circle cx="120" cy="24" r="20" fill="${c}" opacity=".14"/><path d="M80 30 110 47v34L80 98 50 81V47Z" fill="${c}" opacity=".6"/><path d="M80 30 62 93M80 30l31 51M80 98 50 47" stroke="${c}" opacity=".5"/><path d="M96 60h12l4 16-8 7-8-7Z" fill="${c}" opacity=".8"/><path d="m58 74-12 6 6 12 11-4" fill="${c}" opacity=".7"/><path d="M24 128h112" stroke="${c}" stroke-width="2" opacity=".8"/></svg>`;
      case 'simulator': return `<svg class="${cls}" viewBox="0 0 160 145" aria-hidden="true"><circle cx="118" cy="24" r="20" fill="${c}" opacity=".14"/><path d="M40 118V70h16v48h10V84h18v34h10V56h18v62h10V70h16v48h-40-58Z" fill="${c}" opacity=".82"/><path d="M66 46h28" stroke="${c}" stroke-width="7" stroke-linecap="round" opacity=".5"/><path d="M24 128h112" stroke="${c}" stroke-width="2" opacity=".8"/></svg>`;
      case 'platformer': return `<svg class="${cls}" viewBox="0 0 160 145" aria-hidden="true"><circle cx="118" cy="24" r="20" fill="${c}" opacity=".14"/><circle cx="58" cy="96" r="10" fill="${c}"/><path d="M40 112h68v-7h-12l-9-16-25 16-22-9Z" fill="${c}" opacity=".85"/><path d="M40 112h68v-7h-12l-9-16-25 16-22-9Z" fill="${dark}" opacity=".5"/><rect x="36" y="120" width="88" height="6" fill="${c}" opacity=".7"/><path d="M24 128h112" stroke="${c}" stroke-width="2" opacity=".8"/></svg>`;
      case 'racing': return `<svg class="${cls}" viewBox="0 0 160 145" aria-hidden="true"><circle cx="118" cy="24" r="20" fill="${c}" opacity=".14"/><path d="M34 98h92l-10 22H44Z" fill="${c}" opacity=".85"/><path d="M44 108h72M62 98V88h36v10" fill="none" stroke="${dark}" stroke-width="4" stroke-linecap="round"/><circle cx="56" cy="120" r="7" fill="${dark}"/><circle cx="104" cy="120" r="7" fill="${dark}"/><path d="M24 128h112" stroke="${c}" stroke-width="2" opacity=".8"/></svg>`;
      default: return `<svg class="${cls}" viewBox="0 0 160 145" aria-hidden="true"><circle cx="115" cy="38" r="27" fill="${c}" opacity=".18"/><path d="M18 113 62 54l20 25 22-35 38 69Z" fill="${c}" opacity=".75"/><path d="m18 113 42-25 21 13 20-22 41 34Z" fill="${dark}" opacity=".7"/><circle cx="43" cy="48" r="7" fill="${c}"/><path d="M23 126h115" stroke="${c}" stroke-width="2" opacity=".8"/></svg>`;
    }
  }
  modalView(state) { if (this.modal.type === 'create') return this.createModal(state); if (this.modal.type === 'issue') return this.issueModal(state, this.modal.issue); if (this.modal.type === 'release') return this.releaseModal(state); if (this.modal.type === 'reviews') return this.reviewsModal(this.modal.game); if (this.modal.type === 'luck') return this.luckModal(this.modal.result); if (this.modal.type === 'launch') return `<div class="modal-backdrop"><div class="launch-modal"><span class="kicker">Момент релиза</span><strong>${this.modal.countdown || 'В ЭФИРЕ'}</strong><p>${this.modal.countdown ? 'Сборка покидает комнату.' : 'Игроки загружают игру.'}</p></div></div>`; return ''; }
  stars(count) { const filled = '★'.repeat(Math.round(count)); const empty = '☆'.repeat(5 - Math.round(count)); return `<span class="stars" aria-label="${count} из 5"><span class="stars-fill">${filled}</span><span class="stars-empty">${empty}</span></span>`; }
  reviewText(review) { return typeof review === 'string' ? review : review.text; }
  reviewStars(review, fallback) { return typeof review === 'object' && review ? review.stars : fallback; }
  reviewsModal(game) { if (!game) return ''; const items = (game.reviews || []).map((review, index) => `<div class="review-pop"><div class="review-pop-stars">${this.stars(this.reviewStars(review, Math.round((game.rating || 0) / 2)))}</div><p>${esc(this.reviewText(review))}</p><span class="review-author">${index === 0 ? 'Критик' : `Критик · ${index + 1}`}/5</span></div>`).join(''); return `<div class="modal-backdrop"><div class="modal reviews-modal"><div class="modal-head"><div><span class="kicker">Первые отзывы / ${game.year}</span><h2>${esc(game.name)}</h2><p>${outcomeLabels[game.outcome] || game.outcome} · ${game.sales.toLocaleString('ru-RU')} продаж · ${formatMoney(game.revenue)} выручки</p></div><div class="reviews-modal-rating">${this.stars(Math.round((game.rating || 0) / 2))}<strong>${((game.rating || 0) / 2).toFixed(1)}<small>/5</small></strong></div></div><div class="reviews-pop-list">${items}</div><div class="modal-actions"><button class="button primary" data-action="close-modal">Принято <span>→</span></button></div></div></div>`; }
  select(name, options, selected, labels = options) { return `<select name="${name}">${options.map((value, index) => `<option value="${esc(value.id || value)}" ${(value.id || value) === selected ? 'selected' : ''}>${esc(value.label || labels[index])}</option>`).join('')}</select>`; }

  createModal(state) { const defaults = { name: '', genre: 'rpg', setting: 'sci-fi', mechanic: 'exploration', camera: 'Вид сверху', audience: 'Массовая', scope: 'small' }; const f = this.modal.form || defaults; const forecast = this.engine.previewProject(f); return `<div class="modal-backdrop"><div class="modal create-modal"><div class="modal-head"><div><span class="kicker">Новый проект / концепт</span><h2>Что ты создаёшь?</h2><p>Идеального сочетания не существует. Есть только то, что ты решишь довести до конца.</p></div><button class="close-button" data-action="close-modal">×</button></div><form id="create-form"><label class="wide-label">Название проекта<input name="name" maxlength="32" value="${esc(f.name)}" placeholder="Пока без названия" required /></label><div class="form-grid"><label>Жанр${this.select('genre', genres, f.genre)}</label><label>Сеттинг${this.select('setting', settings, f.setting)}</label><label>Главная механика${this.select('mechanic', mechanics, f.mechanic)}</label><label>Камера${this.select('camera', cameras, f.camera)}</label><label>Целевая аудитория${this.select('audience', audiences, f.audience)}</label><label>Масштаб${this.select('scope', scopes, f.scope)}</label></div><div class="hook-preview"><span class="kicker">Крючок игры</span><strong>«${esc(f.name || 'Твоя игра')} — ${esc(forecast.hook)}»</strong><small>Он влияет на инновационность, сложность и потенциал отзывов.</small></div><div class="forecast-grid"><div><span>Привлекательность</span><b>${forecast.appeal}</b></div><div><span>Инновации</span><b>${forecast.innovation}</b></div><div><span>Цена старта</span><b>${formatMoney(Math.round(forecast.cost * 0.35))}</b></div><div><span>Время разработки</span><b>${forecast.months} мес.</b></div><div><span>Риск</span><b class="${forecast.risk > 25 ? 'warning-text' : ''}">${forecast.risk > 30 ? 'Высокий' : forecast.risk > 18 ? 'Средний' : 'Низкий'}</b></div><div><span>Ожидаемая аудитория</span><b>${forecast.audience.toLocaleString('ru-RU')}</b></div></div><div class="modal-actions"><button type="button" class="button ghost" data-action="close-modal">Ещё подумать</button><button type="submit" class="button primary" ${state.money < forecast.cost * 0.35 ? 'disabled' : ''}>Начать разработку <span>→</span></button></div></form></div></div>`; }
  issueModal(state, issueId) { const issue = state.currentProject?.issues.find((entry) => entry.id === issueId); if (!issue) return ''; return `<div class="modal-backdrop"><div class="modal issue-modal"><div class="modal-head"><div><span class="kicker">Решение в сборке</span><h2>${esc(issue.title)}</h2><p>${esc(issue.detail)}</p></div><button class="close-button" data-action="close-modal">×</button></div><div class="decision-options"><button data-action="resolve" data-resolution="fix" data-issue="${issue.id}"><strong>ИСПРАВИТЬ</strong><span>Потратить ${formatMoney(issue.cost)}. Снизить долг и защитить качество.</span></button><button data-action="resolve" data-resolution="workaround" data-issue="${issue.id}"><strong>ОБХОДНОЙ ПУТЬ</strong><span>Потратить меньше сейчас. Взять немного долга.</span></button><button data-action="resolve" data-resolution="postpone" data-issue="${issue.id}"><strong>ОТЛОЖИТЬ</strong><span>Сохранить срок. Пусть риск последует за тобой.</span></button><button data-action="resolve" data-resolution="ignore" data-issue="${issue.id}"><strong>ИГНОРИРОВАТЬ</strong><span>Ничего не платить сейчас. Отзывы всё запомнят.</span></button></div></div></div>`; }
  releaseModal(state) { const p = state.currentProject; const scores = p ? { tech: Math.round(p.progress.programming * 0.58 + p.progress.qa * 0.3 + (100 - p.debt) * 0.12), graphics: Math.round(p.progress.art * 0.8 + p.progress.design * 0.2), innovation: p.forecast.innovation } : {}; const licenses = publishers.map((publisher) => { const available = this.engine.publisherAvailable(publisher, p); const reason = state.reputation < publisher.requirement ? publisher.requirementText : publisher.id === 'northline' && !['medium', 'large', 'huge'].includes(p.scope) ? 'Нужен средний масштаб или больше' : publisher.id === 'silver-pine' && !state.research.includes('online') ? 'Нужно исследование «Сетевой мультиплеер»' : `${publisher.royalty}% роялти`; return `<button class="license-option ${available ? '' : 'locked'}" data-action="launch" data-publisher="${publisher.id}" ${available ? '' : 'disabled'}><div><strong>${publisher.name}</strong><span>${publisher.style}</span></div><b>${available ? `+${formatMoney(publisher.upfront)}` : reason}</b></button>`; }).join(''); return `<div class="modal-backdrop"><div class="modal release-modal"><div class="modal-head"><div><span class="kicker">Игра готова</span><h2>Выпустить сейчас?</h2><p>У сборки есть характер. Рынок решит, что произойдёт дальше.</p></div><button class="close-button" data-action="close-modal">×</button></div><div class="release-summary"><div class="release-cover ${p.genre}">${this.coverArt(p.genre)}<span>404</span><b>${esc(p.name)}</b></div><div class="release-stats"><div><span>Качество</span><b>${Math.round((scores.tech + scores.graphics + p.progress.design + p.progress.writing) / 4)}</b></div><div><span>Техника</span><b>${scores.tech}</b></div><div><span>Инновации</span><b>${scores.innovation}</b></div><div><span>Открытые баги</span><b>${p.issues.filter((issue) => issue.status === 'open').length}</b></div><div><span>Техдолг</span><b>${p.debt}/100</b></div><div><span>Маркетинг</span><b>${p.marketing}</b></div></div></div><div class="license-block"><div class="license-heading"><div><span class="kicker">Лицензия на выпуск</span><strong>Кто поможет донести игру до игроков?</strong></div><span class="muted">Издатель берёт процент с продаж</span></div><button class="license-option self-publish" data-action="launch" data-publisher=""><div><strong>Самостоятельный выпуск</strong><span>Полный контроль и 100% выручки</span></div><b>Без комиссии</b></button>${licenses}</div><div class="modal-actions"><button class="button ghost" data-action="close-modal">Продолжить работу</button></div></div></div>`; }
  creditModal(state) { return `<div class="modal-backdrop"><div class="modal credit-modal"><div class="modal-head"><div><span class="kicker">Финансовая пауза</span><h2>Банк предлагает кредит.</h2><p>Деньги ушли в минус, но студию ещё можно удержать. Кредит спасает текущий месяц, а проценты будут начисляться дальше.</p></div></div><div class="credit-offer"><span>Доступно сейчас</span><strong>${formatMoney(state.pendingCredit)}</strong><small>Лимит ${formatMoney(state.creditLimit)} · уже использовано ${formatMoney(state.creditUsed)}</small></div><div class="credit-warning"><span>!</span><p>Отказ — это не мгновенный сброс. Но если баланс останется ниже ${formatMoney(-5000)}, студия закроется.</p></div><div class="modal-actions"><button class="button ghost" data-action="decline-credit">Отказаться от кредита</button><button class="button primary" data-action="take-credit">Взять ${formatMoney(state.pendingCredit)} <span>→</span></button></div></div></div>`; }
  monthlyReportModal(state) { const report = state.monthlyReport; if (!report) return ''; const monthName = ['Январь', 'Февраль', 'Март', 'Апрель', 'Май', 'Июнь', 'Июль', 'Август', 'Сентябрь', 'Октябрь', 'Ноябрь', 'Декабрь'][(report.month - 1) % 12] || report.month; return `<div class="modal-backdrop"><div class="modal report-modal"><div class="report-banner"><span class="report-brand">${esc(state.logo || '404')}</span><div><strong>СЧЁТ</strong><small>${monthName} ${report.year}</small></div><span class="report-code">№${report.year}-${String(report.month).padStart(2, '0')}</span></div><p class="report-intro">${report.salesCount > 0 ? `За месяц закрыли продажи по ${report.salesCount} проект(ам).` : 'За месяц новых продаж не было.'} Содержание студии списано.</p><div class="report-body"><div class="report-section"><h3>Доход</h3><div class="report-line"><span>Выручка с продаж</span><b class="success-text">+${formatMoney(report.income)}</b></div></div><div class="report-section"><h3>Расход</h3><div class="report-line"><span>Содержание студии (зарплаты, аренда)</span><b>−${formatMoney(report.office)}</b></div>${report.interest ? `<div class="report-line"><span>Проценты по кредитам</span><b class="danger-text">−${formatMoney(report.interest)}</b></div>` : ''}<div class="report-line"><span>Итого расход</span><b>−${formatMoney(report.expenses)}</b></div></div><div class="report-divider"></div><div class="report-total"><span>Итог месяца</span><strong class="${report.net >= 0 ? 'success-text' : 'danger-text'}">${report.net >= 0 ? '+' : '−'}${formatMoney(Math.abs(report.net))}</strong></div><div class="report-balance"><span>Баланс студии на счёте</span><b>${formatMoney(report.money)}</b></div><div class="report-footer"><span>СТУДИЯ 404 · ОФИЦИАЛЬНЫЙ СЧЁТ</span><span>Оплачено</span></div></div><div class="modal-actions"><button class="button primary" data-action="close-report">Продолжить <span>→</span></button></div></div></div>`; }
  bankruptView() { return `<main class="bankrupt"><span class="kicker">${esc(this.engine.getState().studioName || 'Studio 404')} / ${this.engine.getState().year}</span><div class="bankrupt-mark">404</div><h1>Запас денег закончился.</h1><p>Студия потратила всё до следующего релиза. Историю ещё можно начать заново.</p><div class="button-row"><button class="button primary" data-action="reset">Начать новую студию</button></div></main>`; }

  select(name, options, selected, labels = options, unlockedIds = null, currentYear = null) { return `<select name="${name}">${options.map((value, index) => { const optionValue = value.id || value; const eraLocked = currentYear && value.availableFrom && currentYear < value.availableFrom; const locked = (unlockedIds && value.id && !unlockedIds.includes(value.id)) || eraLocked; const suffix = eraLocked ? ` — с ${value.availableFrom} года` : locked ? ' — закрыто' : ''; return `<option value="${esc(optionValue)}" ${optionValue === selected ? 'selected' : ''} ${locked ? 'disabled' : ''}>${esc(value.label || labels[index])}${suffix}</option>`; }).join('')}</select>`; }

  createModal(state) {
    const defaults = { name: '', platform: 'pc', genre: 'rpg', setting: 'sci-fi', mechanic: 'exploration', camera: 'Вид сверху', audience: 'Массовая', scope: 'small', copies: 1000, price: 14.99, miniGameScore: 0 };
    const f = { ...defaults, ...(this.modal.form || {}) }; const step = this.modal.step || 1; const forecast = this.engine.previewProject(f);
    const stepper = `<div class="creation-stepper"><span class="${step >= 1 ? 'active' : ''}">01 Платформа и название</span><i></i><span class="${step >= 2 ? 'active' : ''}">02 Концепция</span><i></i><span class="${step >= 3 ? 'active' : ''}">03 План релиза</span></div>`;
    let body = '';
    if (step === 1) body = `<div class="creation-step"><span class="step-number">01</span><div><h3>С чего начинается игра?</h3><p class="step-copy">Платформа задаёт аудиторию и стоимость входа. Остальные площадки придётся открыть позже.</p><label class="wide-label">Название проекта<input name="name" maxlength="32" value="${esc(f.name)}" placeholder="Пока без названия" required /></label><label class="wide-label">Первая платформа${this.select('platform', platforms, f.platform, platforms, state.unlocks?.platforms || ['pc'], state.year)}</label></div></div>`;
    if (step === 2) body = `<div class="creation-step"><span class="step-number">02</span><div><h3>Из чего состоит идея?</h3><p class="step-copy">Не все жанры и сеттинги доступны сразу. Открывай их за деньги в разделе исследований.</p><div class="form-grid"><label>Жанр${this.select('genre', genres, f.genre, genres, state.unlocks?.genres || [])}</label><label>Сеттинг${this.select('setting', settings, f.setting, settings, state.unlocks?.settings || [])}</label><label>Главная механика${this.select('mechanic', mechanics, f.mechanic)}</label><label>Камера${this.select('camera', cameras, f.camera)}</label><label>Целевая аудитория${this.select('audience', audiences, f.audience)}</label><label>Масштаб${this.select('scope', scopes, f.scope)}</label></div></div></div>`;
    if (step === 3) body = `<div class="creation-step"><span class="step-number">03</span><div><h3>Как ты выпустишь игру?</h3><p class="step-copy">План продаж и маркетинг требуют денег ещё до релиза.</p><div class="form-grid"><label>План продаж (копий)<input type="number" name="copies" min="100" max="100000" step="100" value="${esc(f.copies)}" /></label><label>Цена игры<input type="number" name="price" min="1" max="80" step="0.99" value="${esc(f.price)}" /></label></div><div class="check-row"><label><input type="checkbox" name="trailer" ${f.trailer === 'on' || f.trailer === true ? 'checked' : ''} /> Снять трейлер</label><label><input type="checkbox" name="demo" ${f.demo === 'on' || f.demo === true ? 'checked' : ''} /> Выпустить демо</label></div><div class="forecast-grid"><div><span>Цена старта</span><b>${formatMoney(forecast.startCost)}</b></div><div><span>Срок</span><b>${forecast.months} мес.</b></div><div><span>Аудитория</span><b>${forecast.audience.toLocaleString('ru-RU')}</b></div><div><span>Риск</span><b class="${forecast.risk > 25 ? 'warning-text' : ''}">${forecast.risk > 30 ? 'Высокий' : forecast.risk > 18 ? 'Средний' : 'Низкий'}</b></div></div></div></div>`;
    const back = step > 1 ? '<button type="button" class="button ghost" data-action="form-back">← Назад</button>' : '<button type="button" class="button ghost" data-action="close-modal">Отмена</button>';
    const next = step < 3 ? '<button type="button" class="button primary" data-action="form-next">Дальше <span>→</span></button>' : '<button type="submit" class="button primary">Начать разработку <span>→</span></button>';
    return `<div class="modal-backdrop"><div class="modal create-modal"><div class="modal-head"><div><span class="kicker">Новый проект / концепт</span><h2>Что ты создаёшь?</h2><p>Три коротких решения вместо длинной анкеты. Каждый выбор станет частью релиза.</p></div><button class="close-button" data-action="close-modal">×</button></div>${stepper}<form id="create-form">${body}<div class="modal-actions">${back}${next}</div></form></div></div>`;
  }

  researchPage(state) { const branches = [ { name: 'Искусственный интеллект', icon: 'spark', techs: ['advanced-ai', 'procedural'] }, { name: 'Графика и сеть', icon: 'flask', techs: ['better-rendering', 'advanced-physics', 'online', 'live-service'] }, { name: 'Эксперименты', icon: 'goal', techs: ['vr'] }, { name: 'Сервисы и данные', icon: 'chart', techs: ['cloud-save', 'analytics'] } ]; const node = (id) => { const tech = research.find((t) => t.id === id); if (!tech) return ''; const unlocked = state.research.includes(id); const available = tech.requires.every((r) => state.research.includes(r)); const affordable = state.money >= tech.cost; const cls = unlocked ? 'is-unlocked' : available ? (affordable ? 'is-ready' : 'is-money') : 'is-locked'; const sub = unlocked ? 'Изучено' : available ? formatMoney(tech.cost) : 'Нужно: ' + tech.requires.map((r) => labelFor(research, r)).join(', '); return `<button class="skill-node ${cls}" data-action="research" data-tech="${esc(id)}" ${unlocked || !available || !affordable ? 'disabled' : ''}><span class="node-icon">${unlocked ? '✓' : available ? '⚗' : '◷'}</span><span class="node-name">${esc(tech.label)}</span><span class="node-sub">${sub}</span></button>`; }; const coreHtml = node('optimization'); const branchesHtml = branches.map((br) => `<div class="skill-branch"><div class="branch-head">${icon(br.icon, 15)}${esc(br.name)}</div><div class="branch-nodes">${br.techs.map((id) => node(id)).join('<div class="branch-link"></div>')}</div></div>`).join(''); const content = [...genres.filter((item) => item.unlockCost), ...settings.filter((item) => item.unlockCost), ...platforms.filter((item) => item.unlockCost)].map((item) => { const kind = genres.includes(item) ? 'genres' : settings.includes(item) ? 'settings' : 'platforms'; const unlocked = state.unlocks?.[kind]?.includes(item.id); return `<div class="content-unlock ${unlocked ? 'unlocked' : ''}"><div><strong>${item.label}</strong><span>${unlocked ? 'Открыто для создания игр' : 'Закрыто в начале'}</span></div><button class="small-button" data-action="unlock-content" data-kind="${kind}" data-content="${item.id}" ${unlocked || state.money < item.unlockCost ? 'disabled' : ''}>${unlocked ? 'Открыто' : formatMoney(item.unlockCost)}</button></div>`; }).join(''); return `<div class="page-heading"><div><span class="kicker">Исследования / изучено ${state.research.length} из ${research.length}</span><h1>Дерево исследований.</h1><p class="lede">Каждая ветка открывает новые возможности. Заблокированные узлы ждут своей ветки.</p></div></div><section class="skill-tree"><div class="tree-core">${coreHtml}</div><div class="tree-arrow"></div><div class="skill-branches">${branchesHtml}</div></section><section class="panel content-panel"><div class="panel-head"><div><span class="kicker">Контент и площадки</span><h2>Открывай новые возможности</h2></div><span class="muted">Не всё доступно с первой комнаты</span></div>${content}</section>`; }

  finance(state) { const totalRevenue = state.stats.revenue; const monthlyBurn = 800 + state.team.reduce((sum, member) => sum + (roles.find((role) => role.id === member.role)?.salary || 1000), 0) * 0.24; const debt = state.loans.reduce((sum, loan) => sum + loan.remaining, 0); return `<div class="page-heading"><div><span class="kicker">Финансы / ${state.year}</span><h1>Деньги — ограничение дизайна.</h1><p class="lede">Релиз не выплачивает всё сразу. Доход приходит волнами, а расходы идут каждый месяц.</p></div></div><div class="finance-stats"><div class="stat-card money"><span>Деньги на руках</span><strong>${formatMoney(state.money)}</strong><small>Доступно сейчас</small></div><div class="stat-card"><span>Выручка за всё время</span><strong>${formatMoney(totalRevenue)}</strong><small>После ${state.stats.released} релизов</small></div><div class="stat-card"><span>Расход в месяц</span><strong>${formatMoney(monthlyBurn)}</strong><small>Команда и помещение</small></div></div><section class="panel finance-panel"><div class="panel-head"><div><span class="kicker">Движение денег</span><h2>Что студия уже сделала</h2></div></div><div class="ledger-list"><div><span>Стартовый запас</span><b>${formatMoney(18000)}</b></div><div><span>Выручка с релизов</span><b class="success-text">+${formatMoney(totalRevenue)}</b></div><div><span>Кредитный долг</span><b class="${debt ? 'danger-text' : ''}">${formatMoney(debt)}</b></div><div><span>Текущий баланс</span><b>${formatMoney(state.money)}</b></div></div>${debt ? `<div class="finance-note"><span>!</span><p>Проценты начисляются каждый месяц. <button class="link-button" data-action="repay-credit">Погасить ${formatMoney(Math.min(3000, state.money))}</button></p></div>` : '<div class="finance-note"><span>!</span><p>Когда баланс уйдёт в минус, банк предложит кредит вместо мгновенного сброса студии.</p></div>'}</section>`; }

  postRelease(state) { const game = state.lastRelease; const remaining = game.salesRemaining || 0; return `<section class="release-result panel"><div class="release-result-head"><div><span class="kicker">Последний релиз / ${game.year}</span><h2>${esc(game.name)}</h2><p>${outcomeLabels[game.outcome] || game.outcome}${game.publisher ? ` · издатель ${game.publisher.name}` : ' · самостоятельный выпуск'}</p></div><strong>${game.rating.toFixed(1)}<small>/10</small></strong></div><div class="review-list">${game.reviews.map((review) => `<div class="review-line"><span>“</span><p>${esc(review)}</p></div>`).join('')}</div><div class="release-result-foot"><span>${game.sales.toLocaleString('ru-RU')} продаж</span><span>${remaining.toLocaleString('ru-RU')} потенциальных продаж впереди</span><span>${formatMoney(game.revenue)} выручки</span><button class="button secondary" data-action="nav" data-screen="projects">Открыть библиотеку →</button></div></section>`; }

  bind() { this.root.querySelectorAll('[data-action]').forEach((button) => button.addEventListener('click', (event) => this.action(event.currentTarget))); const form = this.root.querySelector('#create-form'); if (form) { form.addEventListener('input', () => { this.modal.form = { ...this.modal.form, ...Object.fromEntries(new FormData(form).entries()) }; }); form.addEventListener('change', () => { this.modal.form = { ...this.modal.form, ...Object.fromEntries(new FormData(form).entries()) }; this.render(); }); form.addEventListener('submit', (event) => { event.preventDefault(); const data = { ...this.modal.form, ...Object.fromEntries(new FormData(form).entries()) }; if (this.engine.createProject(data)) { this.modal = null; this.toast('Проект начат. Первый месяц за тобой.', 'success'); } else this.toast('Проверь название, доступную платформу и запас денег.', 'warning'); }); } window.onkeydown = (event) => { if (event.key === 'Escape' && this.modal) { this.modal = null; this.render(); } if (event.ctrlKey && event.key.toLowerCase() === 's') { event.preventDefault(); this.engine.save(); this.toast('Прогресс сохранён локально.'); } }; }
  action(button) { const action = button.dataset.action; const state = this.engine.getState(); const newGameModal = () => ({ type: 'create', step: 1, form: { name: '', platform: 'pc', genre: 'rpg', setting: 'sci-fi', mechanic: 'exploration', camera: 'Вид сверху', audience: 'Массовая', scope: 'small', copies: 1000, price: 14.99, miniGameScore: 0 } }); if (action === 'nav') { this.modal = null; this.engine.setScreen(button.dataset.screen); } if (action === 'open-luck') { const result = this.engine.rollCase(button.dataset.case); if (!result) { this.toast('Не хватает денег на этот кейс.', 'warning'); } else { this.modal = { type: 'luck', result }; this.render(); this.toast('Кейс крутится…'); setTimeout(() => this.spinLuck(), 60); } } if (action === 'open-create') { this.modal = newGameModal(); if (!state.tutorialCompleted && state.tutorialStep === 0) this.engine.setTutorialStep(1); this.render(); } if (action === 'tutorial-next') { if ((state.tutorialStep || 0) === 0) { this.engine.setTutorialStep(1); this.modal = newGameModal(); } else if ((state.tutorialStep || 0) === 4) this.engine.setScreen('team'); else this.engine.setTutorialStep((state.tutorialStep || 0) + 1); this.render(); } if (action === 'form-next') { const form = this.root.querySelector('#create-form'); if (form) this.modal.form = { ...this.modal.form, ...Object.fromEntries(new FormData(form).entries()) }; if (this.modal.step < 3) { this.modal.step += 1; this.render(); } } if (action === 'form-back') { if (this.modal.step > 1) { this.modal.step -= 1; this.render(); } } if (action === 'take-credit') { this.engine.takeCredit(); this.toast('Кредит оформлен. Теперь верни студию в плюс.'); } if (action === 'decline-credit') { this.engine.declineCredit(); this.toast('Ты отказался от кредита.', 'warning'); } if (action === 'repay-credit') { this.engine.repayCredit(); this.toast('Платёж по кредиту отправлен.'); } if (action === 'close-modal') { const wasReviews = this.modal?.type === 'reviews'; this.modal = null; this.render(); if (wasReviews) this.engine.unlockTime(); } if (action === 'close-report') { this.engine.clearReport(); this.toast('Месяц закрыт. Время продолжает идти.'); } if (action === 'save') { this.engine.save(); this.toast('Прогресс сохранён локально.'); } if (action === 'pause') this.engine.togglePause(); if (action === 'reset' && window.confirm('Сбросить студию и удалить локальное сохранение?')) { this.engine.reset(); this.toast('Новая студия готова.'); } if (action === 'advance') { this.engine.advanceWeek(button.dataset.mode); this.toast(`Месяц завершён: ${({ proper: 'правильный', normal: 'рабочий', fast: 'быстрый', crunch: 'рывок' })[button.dataset.mode]}.`); } if (action === 'issue') { this.modal = { type: 'issue', issue: button.dataset.issue }; this.render(); } if (action === 'resolve') { this.engine.resolveIssue(button.dataset.issue, button.dataset.resolution); this.modal = null; this.render(); } if (action === 'open-release') { this.modal = { type: 'release' }; this.render(); } if (action === 'launch') this.launch(button.dataset.publisher || null); if (action === 'hire') { this.engine.hire(Number(button.dataset.candidate)); this.toast('Команда изменилась.'); } if (action === 'fire' && window.confirm('Уволить этого сотрудника?')) this.engine.fire(button.dataset.member); if (action === 'upgrade-office') { this.engine.upgradeOffice(); this.toast('Комната стала больше.'); } if (action === 'research') { this.engine.fundResearch(button.dataset.tech); this.toast('Исследование профинансировано.'); } if (action === 'dlc') { this.engine.createDlc(button.dataset.project); this.toast('Дополнение вышло для существующей аудитории.', 'success'); } if (action === 'marketing') { this.engine.addMarketing(button.dataset.marketing); this.toast('У аудитории появилась причина следить за проектом.'); } if (action === 'toggle-setting') this.engine.toggleSetting(button.dataset.setting); }
  postRelease(state) { const game = state.lastRelease; const remaining = game.salesRemaining || 0; return `<section class="release-result panel"><div class="release-result-head"><div><span class="kicker">Последний релиз / ${game.year}</span><h2>${esc(game.name)}</h2><p>${outcomeLabels[game.outcome] || game.outcome}${game.publisher ? ` · издатель ${game.publisher.name}` : ' · самостоятельный выпуск'}</p></div><strong>${game.rating.toFixed(1)}<small>/10</small></strong></div><div class="review-list">${game.reviews.map((review) => `<div class="review-line"><span>“</span><p>${esc(review)}</p></div>`).join('')}</div><div class="release-result-foot"><span>${game.sales.toLocaleString('ru-RU')} продаж сейчас</span><span>${remaining.toLocaleString('ru-RU')} потенциальных продаж впереди</span><span>${formatMoney(game.revenue)} выручки</span><button class="button secondary" data-action="advance-idle">Следующая неделя →</button><button class="button ghost" data-action="nav" data-screen="projects">Библиотека</button></div></section>`; }

  bind() { this.root.querySelectorAll('[data-action]').forEach((button) => button.addEventListener('click', (event) => { if (button.dataset.action === 'form-next' && this.modal?.step === 1) { const form = this.root.querySelector('#create-form'); const data = form ? Object.fromEntries(new FormData(form).entries()) : {}; if (!data.name?.trim()) { event.stopImmediatePropagation(); this.toast('Сначала дай игре название.'); return; } } this.action(event.currentTarget); })); const form = this.root.querySelector('#create-form'); if (form) { form.addEventListener('input', () => { this.modal.form = { ...this.modal.form, ...Object.fromEntries(new FormData(form).entries()) }; }); form.addEventListener('change', () => { this.modal.form = { ...this.modal.form, ...Object.fromEntries(new FormData(form).entries()) }; this.render(); }); form.addEventListener('submit', (event) => { event.preventDefault(); const data = { ...this.modal.form, ...Object.fromEntries(new FormData(form).entries()) }; if (this.engine.createProject(data)) { this.modal = null; this.toast('Проект начат. Первый месяц за тобой.', 'success'); } else this.toast('Проверь название, доступную платформу и запас денег.', 'warning'); }); } window.onkeydown = (event) => { if (event.key === 'Escape' && this.modal) { this.modal = null; this.render(); } if (event.ctrlKey && event.key.toLowerCase() === 's') { event.preventDefault(); this.engine.save(); this.toast('Прогресс сохранён локально.'); } }; }
  launch(publisherId = null) { this.modal = { type: 'launch', countdown: 3, publisherId }; this.render(); let count = 3; clearInterval(this.releaseTimer); this.releaseTimer = setInterval(() => { count -= 1; if (count > 0) { this.modal.countdown = count; this.render(); } else { clearInterval(this.releaseTimer); this.engine.releaseProject(publisherId); this.engine.setScreen('projects'); this.modal = { type: 'reviews', game: this.engine.getState().lastRelease }; this.render(); this.toast('В ЭФИРЕ. Первые отзывы пришли.', 'success'); } }, 700); }
  toast(message, tone = 'info') { const toast = document.createElement('div'); toast.className = `toast ${toneClass(tone)}`; toast.innerHTML = `<span></span>${esc(message)}`; this.toastRegion.appendChild(toast); setTimeout(() => toast.remove(), 3200); }

  team(state) { const skillSummary = (member) => Object.entries(member.skills || roles.find((entry) => entry.id === member.role)?.skills || {}).sort(([, first], [, second]) => second - first).slice(0, 3).map(([skill, value]) => `${disciplineLabels[skill] || skill} ${Math.round(value)}`).join(' · '); const cards = state.team.map((member) => { const role = roles.find((entry) => entry.id === member.role); const trait = traits.find((entry) => entry.id === member.trait); return `<article class="person-card"><div class="person-avatar ${member.role}">${icon(member.role, 22)}</div><div class="person-intro"><span class="kicker">${role?.label || member.role} / уровень ${member.level}</span><h3>${esc(member.name)}</h3><span class="trait">${trait?.label || member.trait} <small>${trait?.effect || ''}</small></span><span class="skill-summary">${skillSummary(member)}</span></div><div class="person-bars"><div class="person-bar"><span>Мораль</span><i><b class="success-fill" style="width:${member.morale}%"></b></i><strong>${member.morale}</strong></div><div class="person-bar"><span>Выгорание</span><i><b class="${member.burnout > 45 ? 'danger-fill' : 'warning-fill'}" style="width:${member.burnout}%"></b></i><strong>${member.burnout}</strong></div></div>${member.isFounder ? '<span class="founder-mark">ОСНОВАТЕЛЬ</span>' : `<button class="icon-link" data-action="fire" data-member="${member.id}">Уволить</button>`}</article>`; }).join(''); const candidates = (state.recruitment || []).map((candidate) => { const role = roles.find((entry) => entry.id === candidate.role); return `<div class="candidate"><div class="candidate-avatar">${icon(candidate.role, 20)}</div><div><strong>${candidate.name}</strong><span>${role.label} · ${traits.find((trait) => trait.id === candidate.trait)?.label}</span><small class="candidate-skills">${skillSummary(candidate)}</small></div><button class="small-button" data-action="hire" data-candidate="${candidate.id}">${`Нанять · ${formatMoney(role.salary * 2)}`}</button></div>`; }).join(''); return `<div class="page-heading"><div><span class="kicker">Люди / ${state.team.length}</span><h1>Люди делают студию.</h1><p class="lede">Навыки видны. Доверие, усталость и отношения — нет.</p></div></div><section class="team-grid">${cards}</section><section class="panel hiring-panel"><div class="panel-head"><div><span class="kicker">Кандидаты этого месяца</span><h2>Кого можно нанять</h2></div><span class="muted">Состав обновляется каждый месяц</span></div><div class="candidate-list">${candidates || '<p class="muted">В этом месяце новых кандидатов нет.</p>'}</div></section>`; }
  bind() {
    this.root.querySelectorAll('[data-action]').forEach((button) => { if (button.dataset.bound) return; button.dataset.bound = '1'; button.addEventListener('click', (event) => {
      if (button.dataset.action === 'pick-logo') { event.preventDefault(); event.stopImmediatePropagation(); this.root.querySelectorAll('.logo-option').forEach((option) => option.classList.remove('is-selected')); button.classList.add('is-selected'); this._brandLogo = button.dataset.logo; return; }
      const action = button.dataset.action;
      if (action === 'form-next' || action === 'form-back') { event.stopImmediatePropagation(); if (action === 'form-next') { const form = this.root.querySelector('#create-form'); const data = form ? Object.fromEntries(new FormData(form).entries()) : {}; this.modal.form = { ...this.modal.form, ...data }; if (this.modal.step === 1 && !this.modal.form.name?.trim()) { this.toast('Сначала дай игре название.'); return; } this.modal.step = Math.min(3, this.modal.step + 1); this.refreshModal(); return; } else if (action === 'form-back') { this.modal.step = Math.max(1, this.modal.step - 1); this.refreshModal(); return; } }
      if (action === 'hire') { event.stopImmediatePropagation(); this.engine.hire(button.dataset.candidate); return; }
      if (action === 'unlock-content') { event.stopImmediatePropagation(); this.engine.unlockContent(button.dataset.kind, button.dataset.content); return; }
      if (action === 'advance-idle') { event.stopImmediatePropagation(); this.engine.advanceWeek('normal'); this.toast('Неделя прошла. Продажи продолжаются.'); return; }
      this.action(event.currentTarget);
    }); });
    const brandForm = this.root.querySelector('#brand-form'); if (brandForm) { brandForm.addEventListener('submit', (event) => { event.preventDefault(); const name = new FormData(brandForm).get('studioName'); const logo = this._brandLogo || '404'; if (this.engine.setBrand(name, logo)) { this.toast(`Студия ${String(name).trim()} основана.`, 'success'); this.render(); } else this.toast('Сначала придумай название студии.', 'warning'); }); }
    const form = this.root.querySelector('#create-form'); if (form) { form.addEventListener('input', () => { this.modal.form = { ...this.modal.form, ...Object.fromEntries(new FormData(form).entries()) }; }); form.addEventListener('change', (event) => { if (event.target.type === 'checkbox') this.modal.form = { ...this.modal.form, ...Object.fromEntries(new FormData(form).entries()) }; else { event.stopImmediatePropagation(); this.modal.form = { ...this.modal.form, ...Object.fromEntries(new FormData(form).entries()) }; this.refreshModal(); } }, true); form.addEventListener('submit', (event) => { event.preventDefault(); const data = { ...this.modal.form, ...Object.fromEntries(new FormData(form).entries()) }; if (this.engine.createProject(data)) { this.modal = null; this.render(); this.toast('Проект начат. Первый месяц за тобой.', 'success'); } else this.toast('Проверь название, доступную платформу и запас денег.', 'warning'); }); }
    window.onkeydown = (event) => { if (event.key === 'Escape' && this.modal) { this.modal = null; this.render(); } if (event.ctrlKey && event.key.toLowerCase() === 's') { event.preventDefault(); this.engine.save(); this.toast('Прогресс сохранён локально.'); } };
  }

  refreshModal() {
    const current = this.root.querySelector('.modal-backdrop'); if (!current || !this.modal) return;
    current.outerHTML = this.modalView(this.engine.getState()); this.bind(); this.root.querySelectorAll('button').forEach((button) => { if (!button.dataset.soundBound) { button.dataset.soundBound = '1'; button.addEventListener('click', () => this.audio?.play('click'), true); } });
  }
  createModal(state) {
    const defaults = { name: '', platform: 'pc', genre: 'rpg', setting: 'sci-fi', mechanic: 'exploration', camera: 'Вид сверху', audience: 'Массовая', scope: 'small', copies: 1000, price: 14.99, miniGameScore: 0 };
    const f = { ...defaults, ...(this.modal.form || {}) }; const step = this.modal.step || 1; const forecast = this.engine.previewProject(f);
    const stepper = `<div class="creation-stepper"><span class="${step >= 1 ? 'active' : ''}">01 Платформа и название</span><i></i><span class="${step >= 2 ? 'active' : ''}">02 Концепция</span><i></i><span class="${step >= 3 ? 'active' : ''}">03 План релиза</span></div>`;
    const body = step === 1 ? `<div class="creation-step"><span class="step-number">01</span><div><h3>С чего начинается игра?</h3><p class="step-copy">Платформа задаёт аудиторию и цену входа. Остальные площадки зависят от года и открываются постепенно.</p><label class="wide-label">Название проекта<input name="name" maxlength="32" value="${esc(f.name)}" placeholder="Пока без названия" required /></label><label class="wide-label">Платформа выпуска${this.select('platform', platforms, f.platform, platforms, state.unlocks?.platforms || ['pc'], state.year)}</label></div></div>` : step === 2 ? `<div class="creation-step"><span class="step-number">02</span><div><h3>Из чего состоит идея?</h3><p class="step-copy">Не все жанры и сеттинги доступны сразу. Открывай новые направления в исследованиях.</p><div class="form-grid"><label>Жанр${this.select('genre', genres, f.genre, genres, state.unlocks?.genres || [])}</label><label>Сеттинг${this.select('setting', settings, f.setting, settings, state.unlocks?.settings || [])}</label><label>Главная механика${this.select('mechanic', mechanics, f.mechanic)}</label><label>Камера${this.select('camera', cameras, f.camera)}</label><label>Целевая аудитория${this.select('audience', audiences, f.audience)}</label><label>Масштаб${this.select('scope', scopes, f.scope)}</label></div></div></div>` : `<div class="creation-step"><span class="step-number">03</span><div><h3>Как ты выпустишь игру?</h3><p class="step-copy">Настрой план продаж и цену игры.</p><div class="range-grid"><label>Первый тираж <output>${Number(f.copies).toLocaleString('ru-RU')}</output><input type="range" name="copies" min="100" max="10000" step="100" value="${esc(f.copies)}" /></label><label>Цена игры <output>$${Number(f.price).toFixed(2)}</output><input type="range" name="price" min="1" max="80" step="0.99" value="${esc(f.price)}" /></label></div><div class="check-row"><label><input type="checkbox" name="trailer" ${f.trailer === 'on' || f.trailer === true ? 'checked' : ''} /> Снять трейлер</label><label><input type="checkbox" name="demo" ${f.demo === 'on' || f.demo === true ? 'checked' : ''} /> Выпустить демо</label></div><div class="forecast-grid"><div><span>Цена старта</span><b>${formatMoney(forecast.startCost)}</b></div><div><span>Срок</span><b>${forecast.months} мес.</b></div><div><span>Аудитория</span><b>${forecast.audience.toLocaleString('ru-RU')}</b></div><div><span>Риск</span><b class="${forecast.risk > 25 ? 'warning-text' : ''}">${forecast.risk > 30 ? 'Высокий' : forecast.risk > 18 ? 'Средний' : 'Низкий'}</b></div></div></div></div>`;
    const back = step > 1 ? '<button type="button" class="button ghost" data-action="form-back">← Назад</button>' : '<button type="button" class="button ghost" data-action="close-modal">Отмена</button>'; const next = step < 3 ? '<button type="button" class="button primary" data-action="form-next">Дальше <span>→</span></button>' : '<button type="submit" class="button primary">Начать разработку <span>→</span></button>';
    return `<div class="modal-backdrop"><div class="modal create-modal"><div class="modal-head"><div><span class="kicker">Новый проект / концепт</span><h2>Что ты создаёшь?</h2><p>Три коротких решения вместо длинной анкеты. Каждый выбор станет частью релиза.</p></div><button class="close-button" data-action="close-modal">×</button></div>${stepper}<form id="create-form"><div class="creation-layout"><div class="creation-art">${this.coverArt(f.genre, true)}<span>${step === 1 ? 'ПЛАТФОРМА' : step === 2 ? 'КОНЦЕПТ' : 'РЕЛИЗ'}</span></div>${body}</div><div class="modal-actions">${back}${next}</div></form></div></div>`;
  }
  projectBoard(state, p) {
    const total = Object.values(p.progress).reduce((sum, value) => sum + value, 0) / 6; const disciplines = Object.entries(p.progress).map(([key, value]) => `<div class="progress-line"><div><span>${disciplineLabels[key] || key}</span><b>${pct(value)}</b></div><div class="progress-track"><i style="width:${value}%"></i></div></div>`).join(''); const issues = p.issues.filter((issue) => issue.status === 'open'); const modes = [['proper', 'Правильно', '−скорость / −долг'], ['normal', 'Обычно', 'стабильно'], ['fast', 'Быстро', '+скорость / +долг'], ['crunch', 'Рывок', '+скорость / выгорание']]; const marketing = [['trailer', 'Трейлер', '$1 800'], ['demo', 'Демо', '$3 200'], ['press', 'Пресса', '$4 500'], ['influencer', 'Блогер', '$6 500']];
    return `<section class="project-board panel"><div class="project-summary"><div><span class="kicker">Текущий проект / ${p.phase === 'release-ready' ? 'Готов к релизу' : 'Время идёт автоматически'}</span><h2>${esc(p.name)}</h2><div class="tag-row"><span class="tag accent">${labelFor(genres, p.genre)}</span><span class="tag">${labelFor(settings, p.setting)}</span><span class="tag">${labelFor(scopes, p.scope)} масштаб</span></div><p class="hook">«${esc(p.hook)}»</p></div><div class="project-percent"><strong>${pct(total)}</strong><span>${p.phase === 'release-ready' ? 'готово' : `месяц ${p.monthsSpent} / ${p.forecast.months}`}</span></div></div><div class="board-body"><div class="discipline-list">${disciplines}</div><div class="board-side"><div class="mini-metric"><span>Давление бюджета</span><b>${formatMoney(Math.max(0, p.forecast.cost - p.monthsSpent * 1300))}</b></div><div class="mini-metric"><span>Технический долг</span><b class="${p.debt > 45 ? 'danger-text' : ''}">${p.debt}/100</b></div><div class="mini-metric"><span>Открытые проблемы</span><b>${issues.length}</b></div></div></div>${issues.length ? `<div class="issues"><div class="issues-title"><span>Проблемы в сборке</span><b>${issues.length}</b></div>${issues.map((issue) => `<div class="issue"><div><strong>${esc(issue.title)}</strong><p>${esc(issue.detail)}</p></div><button class="small-button" data-action="issue" data-issue="${issue.id}">Решить</button></div>`).join('')}</div>` : '<div class="quiet-note">Критических проблем нет. Это не значит, что риска нет.</div>'}<div class="auto-controls"><div><span class="kicker">Автоматический календарь</span><strong>Следующий месяц наступит сам</strong><p>Выбери стиль работы. Пауза появится только для важного решения.</p></div><div class="mode-buttons">${modes.map(([id, label, hint]) => `<button class="mode-button ${state.workMode === id || (!state.workMode && id === 'normal') ? 'active' : ''}" data-action="work-mode" data-mode="${id}"><strong>${label}</strong><small>${hint}</small></button>`).join('')}</div></div><div class="marketing-strip"><div><span class="kicker">Собери аудиторию</span><p>Каждая активность одноразовая для этого проекта.</p></div><div class="marketing-actions">${marketing.map(([id, label, cost]) => `<button class="small-button" data-action="marketing" data-marketing="${id}" ${p.marketingUsed?.includes(id) || p.marketing >= 100 ? 'disabled' : ''}>${label} · ${cost}</button>`).join('')}</div></div>${p.phase === 'release-ready' ? `<div class="ready-banner"><div><span class="kicker">Сборка готова</span><strong>Можно выпускать сейчас или продолжать полировку.</strong></div><button class="button primary" data-action="open-release">Подготовить релиз →</button></div>` : ''}</section>`;
  }

  postRelease(state) { const game = state.lastRelease; const remaining = game.salesRemaining || 0; return `<section class="release-result panel"><div class="release-result-head"><div><span class="kicker">Последний релиз / ${game.year}</span><h2>${esc(game.name)}</h2><p>${outcomeLabels[game.outcome] || game.outcome}${game.publisher ? ` · издатель ${game.publisher.name}` : ' · самостоятельный выпуск'}</p></div><strong>${game.rating.toFixed(1)}<small>/10</small></strong></div><div class="release-result-stars">${this.stars(Math.round(game.rating / 2))}<span>Первые отзывы показали во время релиза.</span></div><div class="release-result-foot"><span>${game.sales.toLocaleString('ru-RU')} продаж сейчас</span><span>${remaining.toLocaleString('ru-RU')} потенциальных продаж впереди</span><span>${formatMoney(game.revenue)} выручки</span><span class="auto-note">Календарь идёт автоматически</span><button class="button ghost" data-action="nav" data-screen="projects">Библиотека</button></div></section>`; }
  onboardingView() { const logos = [['404', 'SP'], ['✦', '▲'], ['◆', '✦'], ['◈', '∴'], ['⬡', '★']]; return `<div class="onboarding"><div class="onboarding-card"><div class="onboarding-mark">404</div><span class="kicker">Первый запуск / студия</span><h1>Дай студии имя.</h1><p class="lede">Название появится в интерфейсе, истории и на обложках релизов. Логотип станет лицом компании.</p><form id="brand-form"><label class="wide-label">Название студии<input name="studioName" maxlength="24" placeholder="Например: Null Games" required autofocus /></label><div class="logo-picker"><span class="kicker">Выбери логотип</span><div class="logo-options"><button type="button" class="logo-option is-selected" data-logo="404" data-action="pick-logo"><span class="logo-glyph">404</span></button><button type="button" class="logo-option" data-logo="SP" data-action="pick-logo"><span class="logo-glyph">SP</span></button><button type="button" class="logo-option" data-logo="▲" data-action="pick-logo"><span class="logo-glyph">▲</span></button><button type="button" class="logo-option" data-logo="◆" data-action="pick-logo"><span class="logo-glyph">◆</span></button><button type="button" class="logo-option" data-logo="⬡" data-action="pick-logo"><span class="logo-glyph">⬡</span></button></div></div><button type="submit" class="button primary">Основать студию <span>→</span></button></form></div></div>`; }
  render() {
    const state = this.engine.getState();
    if (state.bankrupt) { this.root.innerHTML = this.bankruptView(); this.bind(); return; }
    if (!state.branded && (state.history || []).length <= 1) { this.root.innerHTML = this.onboardingView(); this.bind(); return; }
    const nav = navItems.map(([id, label, glyph]) => `<button class="nav-item ${state.screen === id ? 'active' : ''}" data-action="nav" data-screen="${id}"><span class="nav-icon">${icon(id)}</span><span>${label}</span>${id === 'dashboard' && state.events.length ? '<i class="nav-dot"></i>' : ''}</button>`).join('');
    this.root.innerHTML = `<aside class="sidebar ${this.menuOpen ? 'open' : ''}"><div class="brand"><span class="brand-mark">${esc(state.logo || '404')}</span><div><strong>STUDIO</strong><small>${esc(state.studioName || 'Создавай игры')}</small></div></div><nav>${nav}</nav><div class="sidebar-foot"><div class="save-state"><span class="live-dot"></span> Локальное сохранение</div><button class="text-button" data-action="save">Сохранить прогресс <span>Ctrl S</span></button><div class="version">v0.1 / релизный кандидат</div></div></aside>${this.menuOpen ? '<button class="nav-scrim" data-action="toggle-menu" aria-label="Закрыть меню"></button>' : ''}<main class="main"><header class="topbar"><div class="crumb"><button class="mobile-menu-button" data-action="toggle-menu">☰</button><span class="mobile-brand">404</span><span class="eyebrow">${state.screen === 'dashboard' ? 'Рабочий день' : screenLabels[state.screen]}</span><span class="slash">/</span><strong>${screenLabels[state.screen] || 'Главная'}</strong></div><div class="top-actions"><span class="date">${state.month.toString().padStart(2, '0')} / ${state.year} <i class="week-dot">${state.week} нед.</i></span><button class="icon-button ${state.paused ? 'is-paused' : ''}" data-action="pause" title="Пауза">${state.paused ? '▶' : 'Ⅱ'}</button><button class="avatar" data-action="nav" data-screen="team"><span class="avatar-icon">${icon('user', 20)}</span></button></div></header><section class="page-content">${this.page(state)}</section></main>${state.pendingCredit ? this.creditModal(state) : state.monthlyReport ? this.monthlyReportModal(state) : this.modal ? this.modalView(state) : ''}`;
    this.bind();
    this.root.querySelectorAll('button').forEach((button) => { if (!button.dataset.soundBound) { button.dataset.soundBound = '1'; button.addEventListener('click', () => this.audio?.play('click'), true); } });
    this.root.querySelectorAll('[data-action="work-mode"]').forEach((button) => button.addEventListener('click', () => this.engine.setWorkMode(button.dataset.mode)));
    this.root.querySelectorAll('[data-action="marketing"]').forEach((button) => { if (state.currentProject?.marketingUsed?.includes(button.dataset.marketing) || state.currentProject?.marketing >= 100) button.disabled = true; });
    const equipmentHost = this.root.querySelector('.office-info'); if (equipmentHost) { equipmentHost.insertAdjacentHTML('beforeend', `<div class="equipment-shop"><div class="equipment-heading"><span class="kicker">Мастерская</span><strong>Оборудование для офиса</strong></div>${equipment.map((item) => { const owned = state.equipment.includes(item.id); return `<div class="equipment-item ${owned ? 'owned' : ''}"><span class="equipment-icon">${icon(item.id, 18)}</span><div><strong>${item.label}</strong><small>${item.description}</small><em>${item.effect}</em></div><button class="small-button" data-action="buy-equipment" data-equipment="${item.id}" ${owned || state.money < item.cost ? 'disabled' : ''}>${owned ? 'Куплено' : formatMoney(item.cost)}</button></div>`; }).join('')}</div>`); equipmentHost.querySelectorAll('[data-action="buy-equipment"]').forEach((button) => button.addEventListener('click', () => { this.audio?.play('click'); this.engine.buyEquipment(button.dataset.equipment); this.toast('Оборудование установлено.', 'success'); })); }
    this.root.querySelectorAll('input[type="range"]').forEach((input) => input.addEventListener('input', () => { const output = input.closest('label')?.querySelector('output'); if (output) output.textContent = input.name === 'price' ? `$${Number(input.value).toFixed(2)}` : Number(input.value).toLocaleString('ru-RU'); }));
    this.root.querySelectorAll('[data-action="toggle-menu"]').forEach((button) => button.addEventListener('click', (event) => { event.stopImmediatePropagation(); this.menuOpen = !this.menuOpen; this.render(); }, true));
    this.root.querySelectorAll('.nav-item').forEach((button) => button.addEventListener('click', () => { this.menuOpen = false; }, true));
    if (this.root.insertAdjacentHTML && state.saveNotice && Date.now() - state.saveNotice < 1800) this.root.insertAdjacentHTML('beforeend', '<div class="save-indicator"><span></span>Игра сохраняется</div>');
  }

  finance(state) { const totalRevenue = state.stats.revenue; const monthlyBurn = this.engine.monthlyCost(state); const debt = (state.loans || []).reduce((sum, loan) => sum + loan.remaining, 0); return `<div class="page-heading"><div><span class="kicker">Финансы / ${state.year}</span><h1>Деньги — ограничение дизайна.</h1><p class="lede">Релиз не выплачивает всё сразу. Доход приходит волнами, а расходы идут каждый месяц.</p></div></div><div class="finance-stats"><div class="stat-card money"><span>Деньги на руках</span><strong>${formatMoney(state.money)}</strong><small>Доступно сейчас</small></div><div class="stat-card"><span>Выручка за всё время</span><strong>${formatMoney(totalRevenue)}</strong><small>После ${state.stats.released} релизов</small></div><div class="stat-card"><span>Долг студии</span><strong>${formatMoney(debt)}</strong><small>${debt ? 'Проценты каждый месяц' : 'Кредитов нет'}</small></div></div><section class="panel finance-panel"><div class="panel-head"><div><span class="kicker">Движение денег</span><h2>Текущая опора</h2></div></div><div class="ledger-list"><div><span>Стартовый запас</span><b>${formatMoney(9000)}</b></div><div><span>Выручка с релизов</span><b class="success-text">+${formatMoney(totalRevenue)}</b></div><div><span>Расход студии в месяц</span><b>${formatMoney(monthlyBurn)}</b></div><div><span>Текущий баланс</span><b>${formatMoney(state.money)}</b></div></div>${debt ? `<div class="finance-note"><span>!</span><p>Проценты начисляются каждый месяц. <button class="link-button" data-action="repay-credit" ${state.money <= 0 ? 'disabled' : ''}>Погасить ${formatMoney(Math.min(3000, Math.max(0, state.money)))}</button></p></div>` : '<div class="finance-note"><span>!</span><p>Когда баланс уйдёт в минус, банк предложит кредит вместо мгновенного сброса студии.</p></div>'}</section>`; }
}
